                if (LocalContext.NetId.HasValue && LocalContext.NetId.Value != 0) return LocalContext.NetId.Value;
                ulong dra = TurnFlowPatches.GetDraCurrentControlledPlayerId();
                return dra;
            }
            catch { return 0; }
