        public static bool HasP2ReceivedBuffOrResources(CombatState state, Player player2)

        {

            if (player2 == null) return false;

            try

            {

                var creature = player2.Creature;

                if (creature != null)

                {

                    if (creature.Block > 0) return true;

                    if (creature.Powers != null)

                    {

                        foreach (var power in creature.Powers)

                        {

                            if (power == null || power.Amount <= 0) continue;

                            string pname = power.GetType().Name;

                            if (pname.IndexOf("Strength", StringComparison.OrdinalIgnoreCase) >= 0 ||

                                pname.IndexOf("Buffer", StringComparison.OrdinalIgnoreCase) >= 0 ||

                                pname.IndexOf("PlatedArmor", StringComparison.OrdinalIgnoreCase) >= 0)

                            {

                                return true;

                            }

                        }

                    }

                }

                var pCombat = player2.PlayerCombatState;

                if (pCombat != null)

                {

                    if (P2TurnStartEnergy >= 0 && pCombat.Energy > P2TurnStartEnergy) return true;

                    if (P2TurnStartHandCount > 0 && pCombat.Hand != null && pCombat.Hand.Cards != null && pCombat.Hand.Cards.Count > P2TurnStartHandCount) return true;

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] HasP2ReceivedBuffOrResources error: " + ex.Message);

            }

            return false;

        }



        public static int GetCardBaseDamage(CardModel card)

        {

            if (card == null) return 0;

            try

            {

                var dvars = card.DynamicVars;

                if (dvars != null)

                {

                    if (dvars.Damage != null)

                    {

                        return Convert.ToInt32(dvars.Damage.BaseValue);

                    }

                    if (dvars.CalculatedDamage != null)

                    {

                        return Convert.ToInt32(dvars.CalculatedDamage.BaseValue);

                    }

                    if (dvars.ContainsKey("Damage"))

                    {

                        var v = dvars["Damage"];

                        if (v != null) return Convert.ToInt32(v.BaseValue);

                    }

                }

            }

            catch { }

            try

            {

                var canProp = card.GetType().GetProperty("CanonicalVars", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);

                if (canProp != null)

                {

                    var vars = canProp.GetValue(card) as IEnumerable;

                    if (vars != null)

                    {

                        foreach (var v in vars)

                        {

                            if (v == null) continue;

                            var nameProp = v.GetType().GetProperty("Name");

                            if (nameProp != null)

                            {

                                string nameVal = nameProp.GetValue(v) as string;

                                if (string.Equals(nameVal, "Damage", StringComparison.OrdinalIgnoreCase))

                                {

                                    var baseProp = v.GetType().GetProperty("BaseValue");

                                    if (baseProp != null)

                                    {

                                        return Convert.ToInt32(baseProp.GetValue(v));

                                    }

                                }

                            }

                        }

                    }

                }

            }

            catch { }

            return 0;

        }



        public static int CalculateMaxAffordableDamageWithEnergy(Player player, int availableEnergy)

        {

            if (player == null || availableEnergy <= 0) return 0;

            try

            {

                var handPile = PileType.Hand.GetPile(player);

                var cards = (handPile != null && handPile.Cards != null) ? handPile.Cards : null;

                if (cards == null || cards.Count == 0) return 0;



                var attacks = new List<KeyValuePair<int, int>>();

                foreach (var c in cards)

                {

                    if (c == null) continue;

                    if (!IsAttack(c) || !CheckIsPlayable(c)) continue;

                    int cost = Math.Max(0, GetCardEnergyCost(c));

                    int dmg = GetCardBaseDamage(c);

                    if (dmg > 0)

                    {

                        attacks.Add(new KeyValuePair<int, int>(cost, dmg));

                    }

                }



                if (attacks.Count == 0) return 0;



                int[] dp = new int[availableEnergy + 1];

                for (int i = 0; i < attacks.Count; i++)

                {

                    int cost = attacks[i].Key;

                    int dmg = attacks[i].Value;

                    for (int w = availableEnergy; w >= cost; w--)

                    {

                        if (dp[w - cost] + dmg > dp[w])

                        {

                            dp[w] = dp[w - cost] + dmg;

                        }

                    }

                }

                return dp[availableEnergy];

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CalculateMaxAffordableDamageWithEnergy error: " + ex);

                return 0;

            }

        }



        public static int CalculateMaxAffordableDamage(Player player)

        {

            if (player == null || player.PlayerCombatState == null) return 0;

            return CalculateMaxAffordableDamageWithEnergy(player, player.PlayerCombatState.Energy);

        }



        public static bool IsEnemyVulnerable(Creature enemy)

        {

            if (enemy == null || enemy.Powers == null) return false;

            try

            {

                foreach (var p in enemy.Powers)

                {

                    if (p != null && p.Amount > 0)

                    {

                        string pname = p.GetType().Name;

                        if (pname.IndexOf("Vulnerable", StringComparison.OrdinalIgnoreCase) >= 0)

                        {

                            return true;

                        }

                    }

                }

            }

            catch { }

            return false;

        }



        public static bool CheckJointLethalPush(CombatState state, Player player1, Player player2, out string lethalInfo)

        {

            lethalInfo = "";

            if (state == null || state.Enemies == null || player1 == null || player2 == null) return false;

            if (player1.Creature == null || !player1.Creature.IsAlive) return false;

            if (player2.Creature == null || !player2.Creature.IsAlive) return false;



            try

            {

                int est_p2 = CalculateMaxAffordableDamage(player2);

                if (est_p2 <= 0)

                {

                    return false; // Requirement: est_p2 > 0 (pure P1 lethal does not trigger push)

                }



                int est_p1 = CalculateMaxAffordableDamage(player1);



                foreach (var enemy in state.Enemies)

                {

                    if (enemy == null || !enemy.IsAlive || enemy.CurrentHp <= 0) continue;



                    bool isVuln = IsEnemyVulnerable(enemy);

                    double mult = isVuln ? 1.5 : 1.0;

                    int totalEst = (int)Math.Floor(est_p1 * mult) + (int)Math.Floor(est_p2 * mult);



                    if (totalEst >= enemy.CurrentHp)

                    {

                        lethalInfo = string.Format("enemy={0} est_p1={1} est_p2={2} mult={3} hp={4}",

                            enemy.CombatId,

                            est_p1,

                            est_p2,

                            mult.ToString("0.0", System.Globalization.CultureInfo.InvariantCulture),

                            enemy.CurrentHp);

                        GD.Print(string.Format("[AiTeammate][Coord] joint-lethal-push {0}", lethalInfo));

                        return true;

                    }

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CheckJointLethalPush error: " + ex);

            }

            return false;

        }



        public static CoordinatorDecision EvaluateDecision(CombatManager cm, CombatState state, Player player1, Player player2, out string reason)

        {

            reason = "";

            if (player1 == null || player2 == null)

            {

                reason = "missing player";

                return CoordinatorDecision.Immediate;

            }

            if (player1.Creature == null || !player1.Creature.IsAlive)

            {

                reason = "player 1 dead";

                return CoordinatorDecision.Immediate;

            }

            if (player2.Creature == null || !player2.Creature.IsAlive)

            {

                reason = "player 2 dead";

                return CoordinatorDecision.Immediate;

            }



            bool hasLivingEnemies = false;

            if (state != null && state.Enemies != null)

            {

                foreach (var enemy in state.Enemies)

                {

                    if (enemy != null && enemy.IsAlive)

                    {

                        hasLivingEnemies = true;

                        break;

                    }

                }

            }

            if (!hasLivingEnemies)

            {

                reason = "no living enemies";

                return CoordinatorDecision.Immediate;

            }



            // Directive #3.9.2: Joint Lethal Timing Heuristic

            string lethalInfo;

            if (CheckJointLethalPush(state, player1, player2, out lethalInfo))

            {

                reason = "joint-lethal-push: " + lethalInfo;

                return CoordinatorDecision.Immediate;

            }



            try

            {

                // Reset round tracking if round changed

                if (state != null && state.RoundNumber != LastRoundNumber)

                {

                    LastRoundNumber = state.RoundNumber;

                    HasReleasedThisTurn = false;

                    IsWaiting = false;

                }



                var p1Combat = player1.PlayerCombatState;

                var p2Combat = player2.PlayerCombatState;

                if (p1Combat == null || p2Combat == null)

                {

                    reason = "missing player combat state";

                    return CoordinatorDecision.Immediate;

                }



                var p1Hand = p1Combat.Hand != null ? p1Combat.Hand.Cards : null;

                var p2Hand = p2Combat.Hand != null ? p2Combat.Hand.Cards : null;



                // Hand audit logging (Directive #3.9.5: setup:Y(debuff-enemy|buff-ally))

                try

                {

                    var p1Audits = new List<string>();

                    if (p1Hand != null)

                    {

                        int count = 0;

                        foreach (var c in p1Hand)

                        {

                            if (c == null) continue;

                            string id = c.Id.ToString();

                            string sType;

                            bool isSetup = CardIsTeamSetup(c, out sType);

                            string setupStr = isSetup ? ("setup:Y(" + sType + ")") : "setup:N";

                            bool afford = IsAffordable(c, player1);

                            p1Audits.Add(string.Format("{0}({1}/可付:{2})", id, setupStr, afford ? "Y" : "N"));

                            count++;

                            if (count >= 8) break;

                        }

                    }



                    var p2Audits = new List<string>();

                    if (p2Hand != null)

                    {

                        int count = 0;

                        foreach (var c in p2Hand)

                        {

                            if (c == null) continue;

                            string id = c.Id.ToString();

                            bool atk = IsAttack(c);

                            string sType;

                            bool isSetup = CardIsTeamSetup(c, out sType);

                            string setupStr = isSetup ? ("setup:Y(" + sType + ")") : "setup:N";

                            p2Audits.Add(string.Format("{0}(attack:{1}/{2})", id, atk ? "Y" : "N", setupStr));

                            count++;

                            if (count >= 8) break;

                        }

                    }



                    GD.Print("[AiTeammate][Coord] Hand Audit: P1=[" + string.Join(", ", p1Audits) + "], P2=[" + string.Join(", ", p2Audits) + "]");

                }

                catch (Exception exAudit)

                {

                    GD.PrintErr("[AiTeammate][Coord] Hand audit log error: " + exAudit.Message);

                }



                // Condition 1: Player 2's hand has at least one affordable Attack card (cost <= P2 current energy)

                bool p2HasAffordableAttack = false;

                if (p2Hand != null)

                {

                    foreach (var card in p2Hand)

                    {

                        if (card != null && IsAttack(card) && IsAffordable(card, player2))

                        {

                            p2HasAffordableAttack = true;

                            break;

                        }

                    }

                }



                // Condition 2: Player 2's hand has affordable team setup card (debuff-enemy or buff-ally)

                bool p2HasAffordableSetup = false;

                if (p2Hand != null)

                {

                    foreach (var card in p2Hand)

                    {

                        string sType;

                        if (card != null && CardIsTeamSetup(card, out sType) && IsAffordable(card, player2))

                        {

                            p2HasAffordableSetup = true;

                            break;

                        }

                    }

                }



                // Condition 3: Player 1's hand has at least one affordable team setup card

                bool p1HasAffordableSetup = false;

                string p1SetupReason = "";

                int cheapestSetup = int.MaxValue;

                if (p1Hand != null)

                {

                    foreach (var card in p1Hand)

                    {

                        string sType;

                        if (card != null && CheckIsPlayable(card) && CardIsTeamSetup(card, out sType))

                        {

                            int cost = GetCardEnergyCost(card);

                            if (cost < cheapestSetup)

                            {

                                cheapestSetup = cost;

                            }

                            if (IsAffordable(card, player1))

                            {

                                p1HasAffordableSetup = true;

                                p1SetupReason = sType;

                            }

                        }

                    }

                }

                CheapestP1DebuffCost = cheapestSetup;



                // Directive #3.9.5 Decision Rules:

                // Rule 1: If P1 has affordable setup AND P2 has affordable attack -> ALWAYS WAIT!

                if (p1HasAffordableSetup && p2HasAffordableAttack)

                {

                    reason = "P1 has affordable setup (" + p1SetupReason + ") and P2 has affordable attack";

                    return CoordinatorDecision.Wait;

                }



                // Rule 2: If P1 has NO affordable setup, BUT P2 has affordable setup -> ImmediateSetup (ai-setup)

                if (!p1HasAffordableSetup && p2HasAffordableSetup)

                {

                    reason = "ai-setup";

                    return CoordinatorDecision.ImmediateSetup;

                }



                // Rule 3: Otherwise -> Immediate

                reason = "conditions not met (p1Setup=" + p1HasAffordableSetup + ", p2Attack=" + p2HasAffordableAttack + ", p2Setup=" + p2HasAffordableSetup + ", p1Debuff=" + p1HasAffordableSetup + ", p2Debuff=" + p2HasAffordableSetup + ")";

                return CoordinatorDecision.Immediate;

            }

            catch (Exception ex)

            {

                // Fail-open guarantee: default to immediate deployment

                GD.PrintErr("[AiTeammate][Coord] EvaluateDecision exception, fail-open to Immediate: " + ex);

                reason = "exception: " + ex.Message;

                return CoordinatorDecision.Immediate;

            }

        }



        public static void CleanHangingDeployment()

        {

            try

            {

                IsSuppressingCancelHook = true;

                var solverType = AccessTools.TypeByName("CombatSolver.SolverController");

                if (CancelDeploymentMethod == null && solverType != null)

                {

                    CancelDeploymentMethod = AccessTools.Method(solverType, "CancelDeployment");

                }

                if (CancelDeploymentMethod != null)

                {

                    CancelDeploymentMethod.Invoke(null, null);

                }

                else if (solverType != null)

                {

                    if (DeploymentField == null)

                    {

                        DeploymentField = AccessTools.Field(solverType, "_deployment");

                    }

                    if (DeploymentField != null)

                    {

                        DeploymentField.SetValue(null, null);

                    }

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CleanHangingDeployment error: " + ex.Message);

            }

            finally

            {

                IsSuppressingCancelHook = false;

                IsDeploying = false; // Directive #5.35 T1.3: ensure IsDeploying is reset

            }

        }



        public static bool IsFullAutoEnabled()

        {

            try

            {

                var solverType = AccessTools.TypeByName("CombatSolver.SolverController");

                if (solverType == null) return true;

                if (CombatField == null)

                {

                    CombatField = AccessTools.Field(solverType, "_combat");

                }

                if (CombatField != null)

                {

                    object combatObj = CombatField.GetValue(null);

                    if (combatObj != null)

                    {

                        var getter = AccessTools.PropertyGetter(combatObj.GetType(), "FullAutoEnabled")

                            ?? AccessTools.Method(combatObj.GetType(), "get_FullAutoEnabled", Type.EmptyTypes);

                        if (getter != null)

                        {

                            return (bool)getter.Invoke(combatObj, null);

                        }

                    }

                }

            }

            catch { }

            return true;

        }



        public static void EnsureFullAutoEnabled()

        {

            try

            {

                var solverType = AccessTools.TypeByName("CombatSolver.SolverController");

                if (solverType == null) return;



                if (CombatField == null)

                {

                    CombatField = AccessTools.Field(solverType, "_combat");

                }

                if (CombatField != null)

                {

                    object combatObj = CombatField.GetValue(null);

                    if (combatObj != null)

                    {

                        var setter = AccessTools.PropertySetter(combatObj.GetType(), "FullAutoEnabled")

                            ?? AccessTools.Method(combatObj.GetType(), "set_FullAutoEnabled", new Type[] { typeof(bool) });

                        if (setter != null)

                        {

                            setter.Invoke(combatObj, new object[] { true });

                            return;

                        }

                    }

                }



                var controller = CachedSolverController;

                if (controller != null)

                {

                    var setFullAutoMethod = AccessTools.Method(controller.GetType(), "SetFullAuto");

                    if (setFullAutoMethod != null)

                    {

                        var p = setFullAutoMethod.GetParameters();

                        if (p.Length == 1 && p[0].ParameterType == typeof(bool))

                        {

                            setFullAutoMethod.Invoke(controller, new object[] { true });

                        }

                        else if (p.Length == 2)

                        {

                            var cm = CombatManager.Instance;

                            var state = cm != null ? cm.DebugOnlyGetState() : null;

                            setFullAutoMethod.Invoke(controller, new object[] { state, true });

                        }

                        else if (p.Length == 3)

                        {

                            var cm = CombatManager.Instance;

                            var state = cm != null ? cm.DebugOnlyGetState() : null;

                            setFullAutoMethod.Invoke(controller, new object[] { null, state, true });

                        }

                    }

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] EnsureFullAutoEnabled error: " + ex.Message);

            }

        }



        public static void CheckFullAutoGuard()

        {

            try

            {

                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null || state.Players == null || state.Players.Count < 2) return;



                var player2 = state.Players[state.Players.Count - 1];

                if (player2 == null || player2.Creature == null || !player2.Creature.IsAlive) return;



                // Directive #5.34 T0.2: Rate-limit EnsureFullAutoEnabled (not repeated every frame)
                if (!IsFullAutoEnabled())
                {
                    if (LastFullAutoEnsureTurn != TurnNumber && FlowCoordinator.AutoCardRewardEnabled)
                    {
                        LastFullAutoEnsureTurn = TurnNumber;
                        EnsureFullAutoEnabled();
                        GD.Print("[AiTeammate][Coord] full-auto-reenabled turn=" + TurnNumber);
                    }
                }

                // Directive #5.36 T2.3: Keep checking hand ownership until residue or blank hand is resolved
                string _critReason;
                if ((PendingDeferredHandCheckAfterP2 || P2ResidueStartTime != DateTime.MinValue || BlankHandStartTime != DateTime.MinValue) &&
                    !IsInP2HandDeferredPeriod(out _critReason))
                {
                    CheckHandOwnershipGuard(DateTime.UtcNow);
                    if (P2ResidueStartTime == DateTime.MinValue && BlankHandStartTime == DateTime.MinValue)
                    {
                        PendingDeferredHandCheckAfterP2 = false;
                    }
                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CheckFullAutoGuard error: " + ex.Message);

            }

        }



        public static void CheckAutonomousTurnEvaluation(DateTime now)

        {

            try

            {

                // Directive #4.0: Wait/Gatekeeper switch gate

                if (!WaitEnabled) return;

                if (HasAutonomousEvaluatedThisTurn) return;

                if (HasEvaluatedThisTurn) return;

                if (IsPreCombatOrLoading || TurnStartTime == DateTime.MinValue) return;

                if ((now - TurnStartTime).TotalSeconds < 2.5) return;

                if (DeploySeenThisTurn || HasEnteredDeployPrefixThisTurn) return;

                if (IsDeploying) return;

                if (HasCompletedDeploymentThisTurn) return;



                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null || state.Players == null || state.Players.Count < 2) return;



                var p1 = state.Players[0];

                var p2 = state.Players[state.Players.Count - 1];

                if (p1 == null || p2 == null) return;

                if (p2.Creature == null || !p2.Creature.IsAlive) return;



                HasAutonomousEvaluatedThisTurn = true;

                HasEvaluatedThisTurn = true;

                EvaluatedPath = "gatekeeper";



                string reason;

                var decision = EvaluateDecision(cm, state, p1, p2, out reason);

                GD.Print("[AiTeammate][Coord] eval-path=gatekeeper decision=" + decision + " (" + reason + ")");



                if (decision == CoordinatorDecision.Wait)

                {

                    if (HasEnemyDebuff(state))

                    {

                        GD.Print("[AiTeammate][Coord] eval-path=gatekeeper: enemy already debuffed, skipping wait and kicking recalculation");

                        KickSolverRecalculation(state, "autonomous-enemy-already-debuffed");

                        return;

                    }



                    IsWaiting = true;

                    WaitStartTime = now;

                    HasReleasedThisTurn = false;

                    CleanHangingDeployment();

                    GD.Print("[AiTeammate][Coord] Autonomous wait armed (trigger=autonomous-wait, timeout=" + WaitTimeoutSeconds.ToString("F1") + "s)");

                }

                else

                {

                    string trig = (reason != null && reason.IndexOf("joint-lethal-push", StringComparison.OrdinalIgnoreCase) >= 0) ? "autonomous-joint-lethal-push" : "autonomous-immediate";

                    GD.Print("[AiTeammate][Coord] eval-path=gatekeeper: kicking search with deployWhenReady=true (" + trig + ")");

                    KickSolverRecalculation(state, trig);

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CheckAutonomousTurnEvaluation error: " + ex.Message);

            }

        }



        public static MethodInfo FindRequestSearchMethod(Type solverControllerType)

        {

            if (solverControllerType == null) return null;

            var methods = solverControllerType.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static);

            foreach (var m in methods)

            {

                if (m.Name == "RequestSearch")

                {

                    return m;

                }

            }

            return null;

        }



        public static void ResetSolverStateBeforeSearch()

        {

            try

            {

                var solverType = AccessTools.TypeByName("CombatSolver.SolverController");

                if (solverType == null) return;



                // 1. Unfreeze route & resume automatic search on _combat

                if (CombatField == null)

                {

                    CombatField = AccessTools.Field(solverType, "_combat");

                }

                if (CombatField != null)

                {

                    object combatObj = CombatField.GetValue(null);

                    if (combatObj != null)

                    {

                        var routeFrozenSetter = AccessTools.PropertySetter(combatObj.GetType(), "RouteFrozen")

                            ?? AccessTools.Method(combatObj.GetType(), "set_RouteFrozen", new Type[] { typeof(bool) });

                        if (routeFrozenSetter != null)

                        {

                            routeFrozenSetter.Invoke(combatObj, new object[] { false });

                        }



                        var autoPausedSetter = AccessTools.PropertySetter(combatObj.GetType(), "AutomaticSearchPaused")

                            ?? AccessTools.Method(combatObj.GetType(), "set_AutomaticSearchPaused", new Type[] { typeof(bool) });

                        if (autoPausedSetter != null)

                        {

                            autoPausedSetter.Invoke(combatObj, new object[] { false });

                        }

                    }

                }



                // 2. Cancel hanging search (CTS cancel & null _search)

                var cancelSearchMethod = AccessTools.Method(solverType, "CancelSearch");

                if (cancelSearchMethod != null)

                {

                    cancelSearchMethod.Invoke(null, null);

                }



                // 3. Cancel deferred search

                var cancelDeferredMethod = AccessTools.Method(solverType, "CancelDeferredSearch");

                if (cancelDeferredMethod != null)

                {

                    cancelDeferredMethod.Invoke(null, null);

                }



                // 4. Cancel deployment

                CleanHangingDeployment();

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] ResetSolverStateBeforeSearch error: " + ex.Message);

            }

        }



        public static void TryInvokeResetCore()

        {

            try

            {

                var solverType = AccessTools.TypeByName("CombatSolver.SolverController");

                if (solverType != null)

                {

                    var resetCoreMethod = AccessTools.Method(solverType, "ResetCore");

                    if (resetCoreMethod != null)

                    {

                        var pars = resetCoreMethod.GetParameters();

                        if (pars.Length == 0)

                        {

                            resetCoreMethod.Invoke(null, null);

                            GD.Print("[AiTeammate][Coord] ResetCore invoked successfully.");

                        }

                        else if (pars.Length == 1 && pars[0].ParameterType.IsEnum)

                        {

                            object enumZero = Enum.ToObject(pars[0].ParameterType, 0);

                            resetCoreMethod.Invoke(null, new object[] { enumZero });

                            GD.Print("[AiTeammate][Coord] ResetCore(0) invoked successfully.");

                        }

                    }

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] TryInvokeResetCore error: " + ex);

            }

        }



        public static MethodInfo ResolveLiveRequestSearchMethod()

        {

            try

            {

                var liveHost = MegaCrit.Sts2.Core.Nodes.NGame.Instance;

                Type liveHostType = (liveHost != null) ? liveHost.GetType() : typeof(MegaCrit.Sts2.Core.Nodes.NGame);



                // Priority 1: Match param[0].ParameterType == liveHostType exactly across all loaded assemblies

                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())

                {

                    if (asm.GetName().Name == "CombatSolver")

                    {

                        Type scType = asm.GetType("CombatSolver.SolverController");

                        if (scType != null)

                        {

                            var methods = scType.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance);

                            foreach (var m in methods)

                            {

                                if (m.Name == "RequestSearch")

                                {

                                    var pars = m.GetParameters();

                                    if (pars.Length >= 4 && pars[0].ParameterType == liveHostType)

                                    {

                                        return m;

                                    }

                                }

                            }

                        }

                    }

                }



                // Priority 2: Match assembly of liveHostType

                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())

                {

                    if (asm.GetName().Name == "CombatSolver")

                    {

                        Type scType = asm.GetType("CombatSolver.SolverController");

                        if (scType != null)

                        {

                            var methods = scType.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance);

                            foreach (var m in methods)

                            {

                                if (m.Name == "RequestSearch")

                                {

                                    var pars = m.GetParameters();

                                    if (pars.Length >= 4 && pars[0].ParameterType.Assembly == liveHostType.Assembly)

                                    {

                                        return m;

                                    }

                                }

                            }

                        }

                    }

                }



                // Priority 3: Fallback across any CombatSolver assembly

                foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())

                {

                    if (asm.GetName().Name == "CombatSolver")

                    {

                        Type scType = asm.GetType("CombatSolver.SolverController");

                        if (scType != null)

                        {

                            var methods = scType.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance);

                            foreach (var m in methods)

                            {

                                if (m.Name == "RequestSearch")

                                {

                                    return m;

                                }

                            }

                        }

                    }

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] ResolveLiveRequestSearchMethod error: " + ex.Message);

            }

            return RequestSearchMethod;

        }



        public static bool InvokeLiveRequestSearch(CombatState state, string trigger)

        {

            try

            {

                if (state == null)

                {

                    var cm = CombatManager.Instance;

                    if (cm != null) state = cm.DebugOnlyGetState();

                }



                // Directive #5.0.7 T0: Eradicate cross-context NGame ArgumentException by resolving

                // MethodInfo where parameter 0 matches the live NGame.Instance type.

                var targetMethod = ResolveLiveRequestSearchMethod();

                if (targetMethod != null && state != null)

                {

                    var parameters = targetMethod.GetParameters();

                    object[] args = new object[parameters.Length];

                    for (int i = 0; i < parameters.Length; i++)

                    {

                        var p = parameters[i];

                        var pType = p.ParameterType;



                        if (pType.Name == "CombatState" || pType.IsAssignableFrom(typeof(CombatState)) || pType.Name.Contains("CombatState"))

                        {

                            args[i] = state;

                        }

                        else if (pType.Name == "NGame" || typeof(Godot.Node).IsAssignableFrom(pType) || p.Name == "host")

                        {

                            object hostInst = null;

                            if (pType == typeof(MegaCrit.Sts2.Core.Nodes.NGame))

                            {

                                hostInst = MegaCrit.Sts2.Core.Nodes.NGame.Instance;

                            }

                            else

                            {

                                try

                                {

                                    var instProp = pType.GetProperty("Instance", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.FlattenHierarchy);

                                    if (instProp != null) hostInst = instProp.GetValue(null, null);

                                    if (hostInst == null)

                                    {

                                        var instField = pType.GetField("<Instance>k__BackingField", BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.FlattenHierarchy)

                                            ?? pType.GetField("Instance", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.FlattenHierarchy);

                                        if (instField != null) hostInst = instField.GetValue(null);

                                    }

                                }

                                catch { }

                                if (hostInst == null)

                                {

                                    hostInst = MegaCrit.Sts2.Core.Nodes.NGame.Instance;

                                }

                            }

                            args[i] = hostInst ?? (object)CombatManager.Instance;

                        }

                        else if (pType.IsEnum || p.Name.Contains("reason") || pType.Name.Contains("Reason"))

                        {

                            object enumVal = null;

                            try

                            {

                                foreach (var val in Enum.GetValues(pType))

                                {

                                    if (val.ToString().IndexOf("Manual", StringComparison.OrdinalIgnoreCase) >= 0)

                                    {

                                        enumVal = val;

                                        break;

                                    }

                                }

                            }

                            catch { }

                            args[i] = enumVal ?? Enum.ToObject(pType, 0);

                        }

                        else if (pType == typeof(bool))

                        {

                            args[i] = true; // Directive #3.7: deployWhenReady = true so completed searches always deploy

                        }

                        else

                        {

                            args[i] = null;

                        }

                    }



                    targetMethod.Invoke(null, args);

                    RecalcSucceeded = true;

                    return true;

                }

                else

                {

                    GD.PrintErr("[AiTeammate][Coord] KickSolverRecalculation failed: missing method or controller, attempting ResetCore");

                    TryInvokeResetCore();

                    return false;

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] KickSolverRecalculation exception: " + ex);

                TryInvokeResetCore();

                return false;

            }

        }



        public static void KickSolverRecalculation(CombatState state, string trigger)

        {

            DateTime now = DateTime.UtcNow;

            if (trigger == LastKickTrigger && (now - LastKickTime).TotalMilliseconds < 500.0)

            {

                return;

            }

            LastKickTrigger = trigger;

            LastKickTime = now;



            CurrentRecalcGeneration++;

            ReleaseRequestedTime = now;

            RecalcSucceeded = false;

            Watchdog3sFired = false;



            // Reset all solver state: unfreeze route, resume auto, cancel search CTS, cancel deferred, cancel deployment

            ResetSolverStateBeforeSearch();



            // Ensure full auto is enabled

            EnsureFullAutoEnabled();



            GD.Print("[AiTeammate][Coord] recalc-requested trigger=" + trigger + " time=" + ReleaseRequestedTime.ToString("HH:mm:ss.fff"));



            InvokeLiveRequestSearch(state, trigger);

        }



        public static void RefreshPlayerHandVisuals(CombatState state)

        {

            try

            {

                if (IsDeploying) return;

                if (LocalContext.NetId != GetPlayer1NetId()) return;



                bool prevSuppress = ModEntry.SuppressControlSwitchUi;

                ModEntry.SuppressControlSwitchUi = true;

                try

                {

                    if (state == null)

                    {

                        var cm = CombatManager.Instance;

                        if (cm != null)

                        {

                            state = cm.DebugOnlyGetState();

                        }

                    }



                    var hand = NPlayerHand.Instance;

                    if (hand == null) return;



                    ulong p1NetId = GetPlayer1NetId();



                    var holders = hand.ActiveHolders;

                    if (holders != null)

                    {

                        foreach (var h in holders)

                        {

                            if (h != null)

                            {

                                var handHolder = h as MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder;

                                if (handHolder != null && handHolder.CardModel != null && handHolder.CardModel.Owner != null)

                                {

                                    if (handHolder.CardModel.Owner.NetId == p1NetId)

                                    {

                                        handHolder.UpdateCard();

                                    }

                                }

                            }

                        }

                    }

                }

                finally

                {

                    ModEntry.SuppressControlSwitchUi = prevSuppress;

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate] RefreshPlayerHandVisuals error: " + ex.Message);

            }

        }



        public static DateTime LastHandHealTime = DateTime.MinValue;

        public static int ConsecutiveCountMismatchTicks = 0;



        public static void CheckHandOwnershipGuard(DateTime now)
        {
            try
            {
                if (IsDeploying) return;

                var cm = CombatManager.Instance;
                if (cm == null) return;
                var state = cm.DebugOnlyGetState();
                if (state == null || state.Players == null || state.Players.Count < 2) return;

                var player1 = state.Players[0];
                if (player1 == null || player1.Creature == null) return;

                ulong p1NetId = player1.NetId;
                bool isP1Dead = !player1.Creature.IsAlive;
                var hand = MegaCrit.Sts2.Core.Nodes.Combat.NPlayerHand.Instance;
                if (hand == null) return;

                // Directive #5.35 T2.2: If P1 is actively playing/selecting cards, skip guard and clear mismatch tracking
                if (!isP1Dead && IsPlayer1HandBusy(hand))
                {
                    HandMismatchStartTime = DateTime.MinValue;
                    ConsecutiveHandMismatchFrames = 0;
                    P2ResidueStartTime = DateTime.MinValue;
                    ConsecutiveP2ResidueFrames = 0;
                    BlankHandStartTime = DateTime.MinValue;
                    ConsecutiveBlankHandFrames = 0;
                    LastHandOwnershipDeferredReason = "p1-card-play-in-progress";
                    return;
                }

                // Directive #5.34 T1.1: defer during P2 scope or actions
                string deferReason;
                if (IsInP2HandDeferredPeriod(out deferReason))
                {
                    if (deferReason != LastHandOwnershipDeferredReason || (now - LastHandOwnershipDeferredLogTime).TotalMilliseconds >= 500)
                    {
                        LastHandOwnershipDeferredReason = deferReason;
                        LastHandOwnershipDeferredLogTime = now;
                        GD.Print(string.Format("[AiTeammate][Coord] hand-ownership-check-deferred owner=P2 reason={0}", deferReason));
                    }
                    HandMismatchStartTime = DateTime.MinValue;
                    ConsecutiveHandMismatchFrames = 0;
                    P2ResidueStartTime = DateTime.MinValue;
                    ConsecutiveP2ResidueFrames = 0;
                    BlankHandStartTime = DateTime.MinValue;
                    ConsecutiveBlankHandFrames = 0;
                    return; // skip RebindHandContainerToPlayer1
                }

                var holders = hand.ActiveHolders;
                bool hasP2Holder = false;
                if (holders != null)
                {
                    for (int i = 0; i < holders.Count; i++)
                    {
                        var h = holders[i];
                        if (h != null && h.CardModel != null && h.CardModel.Owner != null)
                        {
                            if (TurnCoordinator.IsP2Target(h.CardModel.Owner.NetId))
                            {
                                hasP2Holder = true;
                                break;
                            }
                        }
                    }
                }

                // Directive #5.35 T2.3: Tighten CheckHandOwnershipGuard trigger conditions
                // Branch 1: Actual P2 card residue outside P2 deferred period
                if (hasP2Holder)
                {
                    BlankHandStartTime = DateTime.MinValue;
                    ConsecutiveBlankHandFrames = 0;
                    if (P2ResidueStartTime == DateTime.MinValue) P2ResidueStartTime = now;
                    ConsecutiveP2ResidueFrames++;
                    double residueDuration = (now - P2ResidueStartTime).TotalMilliseconds;
                    if (residueDuration >= 250.0 && ConsecutiveP2ResidueFrames >= 3)
                    {
                        P2ResidueStartTime = DateTime.MinValue;
                        ConsecutiveP2ResidueFrames = 0;
                        HasSelfHealedHandThisTurn = true;
                        LastHandHealTime = now;
                        TotalHandRebindHeals++;

                        // Directive #5.36 T2.3: Precisely remove only P2 card holders if P1 cards exist
                        List<MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder> p2HoldersToRemove = new List<MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder>();
                        int p1HolderCount = 0;
                        if (holders != null)
                        {
                            for (int i = 0; i < holders.Count; i++)
                            {
                                var h = holders[i] as MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder;
                                if (h != null && h.CardModel != null && h.CardModel.Owner != null)
                                {
                                    if (TurnCoordinator.IsP2Target(h.CardModel.Owner.NetId))
                                    {
                                        p2HoldersToRemove.Add(h);
                                    }
                                    else
                                    {
                                        p1HolderCount++;
                                    }
                                }
                            }
                        }

                        if (p2HoldersToRemove.Count > 0 && p1HolderCount > 0)
                        {
                            GD.Print(string.Format("[AiTeammate][Coord] p2-card-residue-pruned count={0} p1HoldersRemaining={1}", p2HoldersToRemove.Count, p1HolderCount));
                            foreach (var ph in p2HoldersToRemove)
                            {
                                try
                                {
                                    hand.RemoveCardHolder(ph);
                                    ph.QueueFree();
                                }
                                catch { }
                            }
                            try { RefreshPlayerHandVisuals(state); } catch { }
                        }
                        else
                        {
                            GD.Print(string.Format("[AiTeammate][Coord] p2-card-residue-leak detected in P1 hand, rebinding to P1 (duration={0:F0}ms frames={1})", residueDuration, ConsecutiveP2ResidueFrames));
                            RebindHandContainerToPlayer1(cm, state, player1);
                        }
                    }
                    return;
                }
                else
                {
                    P2ResidueStartTime = DateTime.MinValue;
                    ConsecutiveP2ResidueFrames = 0;
                }

                // Branch 2: !hasP2Holder. All cards in UI belong to P1.
                int uiHolderCount = holders != null ? holders.Count : 0;
                int p1ModelCardCount = 0;
                try
                {
                    var p1HandPile = MegaCrit.Sts2.Core.Entities.Cards.PileType.Hand.GetPile(player1);
                    if (p1HandPile != null && p1HandPile.Cards != null) p1ModelCardCount = p1HandPile.Cards.Count;
                }
                catch { }

                // If UI has holders, P1 is playing normally - NEVER rebind for mere count differences!
                if (uiHolderCount > 0)
                {
                    BlankHandStartTime = DateTime.MinValue;
                    ConsecutiveBlankHandFrames = 0;
                    HandMismatchStartTime = DateTime.MinValue;
                    ConsecutiveHandMismatchFrames = 0;
                    LastHandOwnershipDeferredReason = null;
                    return;
                }

                // UI is truly blank (uiHolderCount == 0) while P1 model has cards (p1ModelCardCount > 0)
                if (p1ModelCardCount > 0 && !isP1Dead && !IsPlayer1HandBusy(hand))
                {
                    if (BlankHandStartTime == DateTime.MinValue) BlankHandStartTime = now;
                    ConsecutiveBlankHandFrames++;
                    double blankDuration = (now - BlankHandStartTime).TotalMilliseconds;
                    if (blankDuration >= 500.0 && ConsecutiveBlankHandFrames >= 5)
                    {
                        BlankHandStartTime = DateTime.MinValue;
                        ConsecutiveBlankHandFrames = 0;
                        HasSelfHealedHandThisTurn = true;
                        LastHandHealTime = now;
                        TotalHandRebindHeals++;
                        GD.Print(string.Format("[AiTeammate][Coord] blank-hand-leak detected (modelCards={0}, uiHolders=0), rebinding to P1 (duration={1:F0}ms frames={2})", p1ModelCardCount, blankDuration, ConsecutiveBlankHandFrames));
                        RebindHandContainerToPlayer1(cm, state, player1);
                    }
                }
                else
                {
                    BlankHandStartTime = DateTime.MinValue;
                    ConsecutiveBlankHandFrames = 0;
                }
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] CheckHandOwnershipGuard error: " + ex);
            }
        }

        public static void RebindHandContainerToPlayer1(CombatManager cm, CombatState state, Player player1)

        {
            if (TurnCoordinator.IsTerminalCombatFinalized || TurnCoordinator.AreAllPlayersDead())
            {
                TurnCoordinator.LogTerminalCombatFinalized("all-players-dead");
                return;
            }

            // Directive #5.35 T2.4: Never rebuild hand while P1 is busy playing cards
            if (player1 != null && player1.Creature != null && player1.Creature.IsAlive)
            {
                var handCheck = MegaCrit.Sts2.Core.Nodes.Combat.NPlayerHand.Instance;
                if (handCheck != null && IsPlayer1HandBusy(handCheck))
                {
                    GD.Print("[AiTeammate][Coord] RebindHandContainerToPlayer1 deferred: P1 card play in progress");
                    return;
                }
            }

            TurnCoordinator.P1InputLockDepth++; GD.Print("[AiTeammate][Coord] input-lock-window begin=hand-rebuild");
            bool prevSuppress = ModEntry.SuppressControlSwitchUi;

            // Directive #5.0.5 Task 0: Unsuppress UI to allow full combat UI refresh for P1 after full 5-container holder purge

            ModEntry.SuppressControlSwitchUi = false;

            try

            {

                if (player1 == null) return;

                bool isP1Dead = player1.Creature == null || !player1.Creature.IsAlive;



                var hand = NPlayerHand.Instance;

                if (hand == null) return;



                try

                {

                    if (!hand.InCardPlay)

                    {

                        hand.CancelAllCardPlay();

                    }

                }

                catch { }



                // Step 1 (Directive #5.0.5 Task 0): ALWAYS purge all residual holders across all 5 containers FIRST

                var nodesToPurge = new List<Node>();



                // Container A: ActiveHolders

                try

                {

                    var active = hand.ActiveHolders;

                    if (active != null)

                    {

                        foreach (var h in active)

                        {

                            if (h != null && GodotObject.IsInstanceValid(h) && !nodesToPurge.Contains(h)) nodesToPurge.Add(h);

                        }

                    }

                }

                catch { }



                // Container B: Holders (private property IReadOnlyList<NHandCardHolder>)

                try

                {

                    var holdersProp = AccessTools.Property(hand.GetType(), "Holders");

                    var holders = holdersProp != null ? holdersProp.GetValue(hand, null) as System.Collections.IEnumerable : null;

                    if (holders != null)

                    {

                        foreach (var obj in holders)

                        {

                            var h = obj as Node;

                            if (h != null && GodotObject.IsInstanceValid(h) && !nodesToPurge.Contains(h)) nodesToPurge.Add(h);

                        }

                    }

                }

                catch { }



                // Container C: CardHolderContainer.GetChildren()

                var container = hand.CardHolderContainer;

                if (container != null && GodotObject.IsInstanceValid(container))

                {

                    try

                    {

                        var children = container.GetChildren();

                        if (children != null)

                        {

                            foreach (var child in children)

                            {

                                if (child != null && GodotObject.IsInstanceValid(child) && !nodesToPurge.Contains(child)) nodesToPurge.Add(child);

                            }

                        }

                    }

                    catch { }

                }



                // Container D: NPlayerHand direct children (catches reparented holders during StartCardPlay)

                try

                {

                    var handChildren = hand.GetChildren();

                    if (handChildren != null)

                    {

                        foreach (var child in handChildren)

                        {

                            if (child != null && GodotObject.IsInstanceValid(child))

                            {

                                string tname = child.GetType().Name;

                                if ((child is MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder ||

                                    tname == "NCardPlay" ||

                                    tname.Contains("CardHolder")) && !nodesToPurge.Contains(child))

                                {

                                    nodesToPurge.Add(child);

                                }

                            }

                        }

                    }

                }

                catch { }



                // Container E: Internal _holdersAwaitingQueue & _selectedHandCardContainer via reflection

                try

                {

                    var queueField = AccessTools.Field(hand.GetType(), "_holdersAwaitingQueue");

                    if (queueField != null)

                    {

                        var queue = queueField.GetValue(hand) as System.Collections.IEnumerable;

                        if (queue != null)

                        {

                            foreach (var item in queue)

                            {

                                var n = item as Node;

                                if (n != null && GodotObject.IsInstanceValid(n) && !nodesToPurge.Contains(n)) nodesToPurge.Add(n);

                            }

                        }

                    }



                    var selectedField = AccessTools.Field(hand.GetType(), "_selectedHandCardContainer");

                    if (selectedField != null)

                    {

                        var selCont = selectedField.GetValue(hand) as Node;

                        if (selCont != null && GodotObject.IsInstanceValid(selCont))

                        {

                            var selChildren = selCont.GetChildren();

                            if (selChildren != null)

                            {

                                foreach (var sc in selChildren)

                                {

                                    if (sc != null && GodotObject.IsInstanceValid(sc) && !nodesToPurge.Contains(sc)) nodesToPurge.Add(sc);

                                }

                            }

                        }

                    }

                }

                catch { }



                int purgedCount = nodesToPurge.Count;



                // Purge all collected nodes

                foreach (var node in nodesToPurge)

                {

                    try

                    {

                        if (node == null || !GodotObject.IsInstanceValid(node)) continue;



                        var holder = node as MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder;

                        if (holder != null)

                        {

                            try

                            {

                                hand.RemoveCardHolder(holder);

                            }

                            catch { }

                        }



                        if (GodotObject.IsInstanceValid(node))

                        {

                            var parent = node.GetParent();

                            if (parent != null)

                            {

                                parent.RemoveChild(node);

                            }

                            node.QueueFree();

                        }

                    }

                    catch { }

                }



                // Clear internal references via reflection

                try

                {

                    var queueField = AccessTools.Field(hand.GetType(), "_holdersAwaitingQueue");

                    if (queueField != null)

                    {

                        var queueList = queueField.GetValue(hand) as System.Collections.IList;

                        if (queueList != null) queueList.Clear();

                    }



                    // Directive #5.35 T2.4: Only reset _currentCardPlay if hand is not in card play
                    if (!hand.InCardPlay)
                    {
                        var cardPlayField = AccessTools.Field(hand.GetType(), "_currentCardPlay");
                        if (cardPlayField != null)
                        {
                            cardPlayField.SetValue(hand, null);
                        }
                    }

                }

                catch { }



                // Step 2: Restore LocalContext to P1 (when alive) and invoke DRA RefreshCombatUiForControlledPlayer unsuppressed

                if (!isP1Dead)

                {

                    try

                    {

                        LocalContext.NetId = player1.NetId;

                    }

                    catch { }

                }



                bool draRefreshed = false;

                if (!isP1Dead)

                {

                    try

                    {

                        var multiRuntimeType = AccessTools.TypeByName("LocalMultiControl.Scripts.Runtime.LocalMultiControlRuntime");

                        if (multiRuntimeType != null)

                        {

                            var refreshMethod = AccessTools.Method(multiRuntimeType, "RefreshCombatUiForControlledPlayer", new Type[] { typeof(ulong) });

                            if (refreshMethod != null)

                            {

                                GD.Print(string.Format("[AiTeammate][Coord] hand-rebind: invoking DRA RefreshCombatUiForControlledPlayer for P1 at line 1788 (p1={0} dead={1})", player1.NetId, isP1Dead));

                                object ret = refreshMethod.Invoke(null, new object[] { player1.NetId });

                                if (ret is bool && (bool)ret)

                                {

                                    draRefreshed = true;

                                }

                            }

                        }

                    }

                    catch (Exception exDra)

                    {

                        GD.PrintErr("[AiTeammate][Coord] DRA RefreshCombatUiForControlledPlayer failed, using explicit rebuild: " + exDra);

                    }

                }



                // Step 3: Verify P1 hand cards and pile subscriptions; if DRA deferred or count mismatches, rebuild explicitly

                var handPile = PileType.Hand.GetPile(player1);

                int expectedCount = (!isP1Dead && handPile != null && handPile.Cards != null) ? handPile.Cards.Count : 0;

                int currentHolderCount = (hand.ActiveHolders != null) ? hand.ActiveHolders.Count : 0;



                bool draSuccess = draRefreshed;

                if (draSuccess)

                {

                    if (currentHolderCount == expectedCount && !isP1Dead)

                    {

                        GD.Print("[AiTeammate][Coord] Hand container rebound to Player 1 via DRA RefreshCombatUiForControlledPlayer.");

                        return;

                    }

                }



                if (!isP1Dead && (!draSuccess || currentHolderCount != expectedCount))

                {

                    // Ensure no half-added holders remain before explicit rebuild

                    try

                    {

                        if (hand.ActiveHolders != null && hand.ActiveHolders.Count > 0)

                        {

                            var copy = new List<MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder>(hand.ActiveHolders);

                            foreach (var h in copy)

                            {

                                if (h != null && GodotObject.IsInstanceValid(h))

                                {

                                    try { hand.RemoveCardHolder(h); } catch { }

                                    try { h.QueueFree(); } catch { }

                                }

                            }

                        }

                    }

                    catch { }



                    if (handPile != null && handPile.Cards != null)

                    {

                        foreach (var card in handPile.Cards)

                        {

                            if (card != null)

                            {

                                var nCard = NCard.Create(card, (ModelVisibility)1);

                                if (nCard != null)

                                {

                                    hand.Add(nCard, -1);

                                }

                            }

                        }

                    }

                }



                hand.ForceRefreshCardIndices();



                var room = NCombatRoom.Instance;

                var combatUi = room != null ? room.Ui : null;

                if (combatUi != null)

                {

                    if (!isP1Dead && !draRefreshed)

                    {

                        // Re-initialize Draw/Discard/Exhaust piles for P1 so pile counts & signals stay bound

                        try

                        {

                            string[] pileProps = new string[] { "DrawPile", "DiscardPile", "ExhaustPile" };

                            for (int i = 0; i < pileProps.Length; i++)

                            {

                                var pProp = AccessTools.Property(combatUi.GetType(), pileProps[i]);

                                object pileNode = pProp != null ? pProp.GetValue(combatUi, null) : null;

                                if (pileNode != null)

                                {

                                    var initMethod = AccessTools.Method(pileNode.GetType(), "Initialize", new Type[] { typeof(Player) });

                                    if (initMethod != null) initMethod.Invoke(pileNode, new object[] { player1 });

                                }

                            }

                        }

                        catch { }

                    }



                    if (combatUi.EndTurnButton != null)

                    {

                        var playerHandField = AccessTools.Field(combatUi.EndTurnButton.GetType(), "_playerHand");

                        if (playerHandField != null)

                        {

                            playerHandField.SetValue(combatUi.EndTurnButton, isP1Dead ? null : handPile);

                        }

                    }

                }



                if (!isP1Dead)

                {

                    RefreshPlayerHandVisuals(state);

                }



                // Directive #5.12 H7: Silent hand rebuild - suppress dealing tween/animations and instantly snap positions

                try

                {

                    hand.ForceRefreshCardIndices();

                    if (hand.ActiveHolders != null)

                    {

                        foreach (var h in hand.ActiveHolders)

                        {

                            if (h != null && GodotObject.IsInstanceValid(h))

                            {

                                try

                                {

                                    MethodInfo stopAnim = AccessTools.Method(typeof(MegaCrit.Sts2.Core.Nodes.Cards.Holders.NHandCardHolder), "StopAnimations");

                                    if (stopAnim != null) stopAnim.Invoke(h, null);

                                    h.SetDefaultTargets();

                                    h.Position = h.TargetPosition;

                                    h.SetAngleInstantly(h.TargetAngle);

                                    h.SetScaleInstantly(Godot.Vector2.One);

                                }

                                catch { }

                            }

                        }

                    }

                }

                catch { }



                int rebuiltCount = (hand.ActiveHolders != null) ? hand.ActiveHolders.Count : 0;

                GD.Print(string.Format("[AiTeammate][Coord] hand-holder-purge-rebuild purged={0} rebuilt={1} p1={2} dead={3} draRefreshed={4}", purgedCount, rebuiltCount, player1.NetId, isP1Dead, draRefreshed));

                GD.Print("[AiTeammate][Coord] Hand container successfully rebound to Player 1 (" + player1.NetId + "). alive=" + (!isP1Dead) + " cardCount=" + rebuiltCount + " purgedNodes=" + purgedCount);

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] RebindHandContainerToPlayer1 error: " + ex);

            }

            finally

            {

                ModEntry.SuppressControlSwitchUi = prevSuppress;

                TurnCoordinator.P1InputLockDepth = Math.Max(0, TurnCoordinator.P1InputLockDepth - 1); GD.Print("[AiTeammate][Coord] input-lock-window end=hand-rebuild");
            }

        }



        public static void CheckControlDivergenceGuard(DateTime now)

        {

            try

            {

                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null || state.Players == null || state.Players.Count < 2) return;



                var p1 = state.Players[0];

                if (p1 == null || p1.Creature == null || !p1.Creature.IsAlive)

                {

                    ConsecutiveDivergenceTicks = 0;

                    TransientIgnoredCount = 0;

                    return;

                }



                ulong p1NetId = p1.NetId;

                var p2 = state.Players[state.Players.Count - 1];

                ulong p2NetId = (p2 != null) ? p2.NetId : 0;

                ulong localNetId = LocalContext.NetId.HasValue ? LocalContext.NetId.Value : 0;

                ulong draSessionId = TurnFlowPatches.GetDraCurrentControlledPlayerId();



                // Directive #3.9.1: Divergence condition: localContext == P2 and draSession == P1 (or localContext != P1)

                bool isDiverged = (localNetId == p2NetId && (draSessionId == p1NetId || draSessionId == 0));



                if (isDiverged)

                {

                    // Directive #5.11 H1: Divergence exemption during pending choice or gathering player choice

                    if (P2PendingChoiceCount > 0 || IsP2ActionGatheringChoice(p2NetId))

                    {

                        ConsecutiveDivergenceTicks = 0;

                        TransientIgnoredCount = 0;

                        if ((now - LastDivergenceDeferLogTime).TotalSeconds >= 1.5)

                        {

                            LastDivergenceDeferLogTime = now;

                            GD.Print(string.Format("[AiTeammate][Coord] divergence-deferred-during-pending-choice: pendingChoice={0}, gatheringChoice={1}", P2PendingChoiceCount, IsP2ActionGatheringChoice(p2NetId)));

                        }

                        return;

                    }



                    ConsecutiveDivergenceTicks++;



                    // Persistence threshold requires:

                    // 1. Consecutive >= 3 tick samples (>= 1.5 seconds)

                    // 2. IsDeploying == false

                    // 3. Time since last PlayCardAction > 2.0 seconds

                    bool persistent = (ConsecutiveDivergenceTicks >= 3);

                    bool actionQuiet = (LastActionExecutedTime == DateTime.MinValue || (now - LastActionExecutedTime).TotalSeconds > 2.0);



                    if (!persistent || !actionQuiet || IsDeploying)

                    {

                        // Transient divergence (e.g. during card execution sequence). Suppress healing.

                        TransientIgnoredCount++;

                        if ((now - LastTransientLogTime).TotalSeconds >= 1.5)

                        {

                            LastTransientLogTime = now;

                            GD.Print(string.Format("[AiTeammate][Coord] divergence-transient-ignored x{0}", TransientIgnoredCount));

                        }

                        return;

                    }



                    // Persistent threshold satisfied!

                    if ((now - LastDivergenceHealTime).TotalSeconds >= 1.0)

                    {

                        LastDivergenceHealTime = now;

                        GD.PrintErr(string.Format("[AiTeammate][Coord] control-divergence detected (localContext={0}, draSession={1}, p1={2}), persistent >=1.5s, recovering control to P1 (logic unsuppressed, UI suppressed)", localNetId, draSessionId, p1NetId));

                        TurnFlowPatches.SwitchControlToPlayer(p1NetId, "wakuu-divergence-heal", true);

                        TurnFlowPatches.RefreshPlayer1CombatUiMinimal();

                        ConsecutiveDivergenceTicks = 0;

                        TransientIgnoredCount = 0;

                    }

                }

                else

                {

                    ConsecutiveDivergenceTicks = 0;

                    TransientIgnoredCount = 0;

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CheckControlDivergenceGuard error: " + ex);

            }

        }



        public static int GetPlayerHandCardCount(Player player)

        {

            if (player == null) return 0;

            try

            {

                var pile = PileType.Hand.GetPile(player);

                if (pile != null && pile.Cards != null)

                {

                    return pile.Cards.Count;

                }

            }

            catch { }

            try

            {

                var handProp = player.GetType().GetProperty("Hand", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);

                if (handProp != null)

                {

                    var handObj = handProp.GetValue(player) as ICollection;

                    if (handObj != null) return handObj.Count;

                }

            }

            catch { }

            return 0;

        }



        public static int GetPlanActionCount(object[] args)

        {

            if (args == null) return -1;

            for (int i = 0; i < args.Length; i++)

            {

                var arg = args[i];

                if (arg == null) continue;

                try

                {

                    var propBestNode = arg.GetType().GetProperty("BestNode", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);

                    if (propBestNode != null)

                    {

                        var bestNode = propBestNode.GetValue(arg);

                        if (bestNode != null)

                        {

                            int c = ExtractCountFromPlan(bestNode);

                            if (c >= 0) return c;

                        }

                    }



                    int direct = ExtractCountFromPlan(arg);

                    if (direct >= 0) return direct;

                }

                catch { }

            }

            return -1;

        }

        private static object FindPlanObject(object[] args)
        {
            if (args == null) return null;
            for (int i = 0; i < args.Length; i++)
            {
                object arg = args[i];
                if (arg == null) continue;
                try
                {
                    object best = GetMemberValue(arg, "BestNode");
                    if (best != null && (GetMemberValue(best, "Actions") != null || GetMemberValue(best, "ActionCount") != null)) return best;
                    if (GetMemberValue(arg, "Actions") != null || GetMemberValue(arg, "Plan") != null || GetMemberValue(arg, "ActionCount") != null) return arg;
                }
                catch { }
            }
            return null;
        }

        private static IEnumerable GetPlanActions(object planObj)
        {
            if (planObj == null) return null;
            object actions = GetMemberValue(planObj, "Actions") ?? GetMemberValue(planObj, "Plan");
            return actions as IEnumerable;
        }

        public static void RecordPlanTelemetry(object[] args, string source)
        {
            try
            {
                int count = GetPlanActionCount(args);
                if (count >= 0) P2PlanLengthThisTurn = count;
                object plan = FindPlanObject(args);
                IEnumerable actions = GetPlanActions(plan);
                if (actions == null)
                {
                    // Directive #5.87: this entry point could not resolve a plan object. Keep the
                    // last known plan telemetry instead of zeroing it (a zeroed plan is what made
                    // DeployCurrentTurn look "plan-empty" while a real 34-action plan existed).
                    UpdateSearchTelemetry(source);
                    GD.Print(string.Format("[AiTeammate][Coord] p2-plan-observed turn={0} plan-len={1} plan-card={2} plan-attack={3} search-status={4} search-nodes={5} source={6} plan-unavailable=1", TurnNumber, P2PlanLengthThisTurn, P2PlanHasCardActionThisTurn, P2PlanHasAttackThisTurn, P2SearchStatusThisTurn, P2SearchNodesThisTurn, source ?? "unknown"));
                    return;
                }
                P2PlanHasAttackThisTurn = false;
                P2PlanHasCardActionThisTurn = false;
                int planActionIdx = 0;
                int endTurnIdx = -1;
                int totalPlanCardActions = 0;
                List<string> plannedCards = new List<string>();
                if (actions != null)
                {
                    foreach (object action in actions)
                    {
                        if (action == null) { planActionIdx++; continue; }
                        string kindStr = GetMemberValue(action, "Kind") != null ? GetMemberValue(action, "Kind").ToString() : action.GetType().Name;
                        bool endsTurn = false;
                        object endsTurnObj = GetMemberValue(action, "EndsPlayerTurn");
                        if (endsTurnObj is bool) endsTurn = (bool)endsTurnObj;
                        bool isPlayCardAction = kindStr.IndexOf("PlayCard", StringComparison.OrdinalIgnoreCase) >= 0;
                        bool isEndTurnAction = endsTurn || kindStr.IndexOf("EndTurn", StringComparison.OrdinalIgnoreCase) >= 0;
                        // Directive #5.88 T1: CombatSolver.PlanActionKind = { PlayCard=0, UsePotion=1,
                        // EndTurn=2 } and a Plan.Actions list spans several future turns split by
                        // EndTurn entries. "boundaryBefore" is the turn boundary known BEFORE this
                        // action, so a card that itself ends the turn still counts as this turn's card
                        // while every action after the first boundary is ignored.
                        int boundaryBefore = endTurnIdx;
                        if (isPlayCardAction)
                        {
                            totalPlanCardActions++;
                            if (boundaryBefore < 0)
                            {
                                P2PlanHasCardActionThisTurn = true;
                                // Directive #5.88: CombatSolver.PlanAction exposes "CardId" (string), not a
                                // CardModel, which is why the old log only ever showed synthetic card_N ids.
                                object cardIdObj = GetMemberValue(action, "CardId");
                                string cid = cardIdObj != null ? cardIdObj.ToString() : null;
                                if (string.IsNullOrEmpty(cid))
                                {
                                    CardModel card = GetMemberValue(action, "Card") as CardModel ?? GetMemberValue(action, "CardModel") as CardModel;
                                    cid = card != null && card.Id != null ? card.Id.ToString() : "card_" + planActionIdx;
                                    if (card != null && IsAttack(card)) P2PlanHasAttackThisTurn = true;
                                }
                                plannedCards.Add(cid);
                            }
                        }
                        if (isEndTurnAction && endTurnIdx < 0) endTurnIdx = planActionIdx;
                        planActionIdx++;
                    }
                }
                P2PlannedCardActionsThisTurn = plannedCards.Count;
                string plannedCardsStr = plannedCards.Count > 0 ? string.Join(",", plannedCards.ToArray()) : "none";
                GD.Print(string.Format("[AiTeammate][Coord] solver-plan-inspect turn={0} planned-card-actions={1} end-turn-index={2} total-plan-card-actions={3}", TurnNumber, plannedCardsStr, endTurnIdx, totalPlanCardActions));
                UpdateSearchTelemetry(source);
                GD.Print(string.Format("[AiTeammate][Coord] p2-plan-observed turn={0} plan-len={1} plan-card={2} plan-attack={3} search-status={4} search-nodes={5} source={6}", TurnNumber, P2PlanLengthThisTurn, P2PlanHasCardActionThisTurn, P2PlanHasAttackThisTurn, P2SearchStatusThisTurn, P2SearchNodesThisTurn, source ?? "unknown"));
            }
            catch (Exception ex) { GD.PrintErr("[AiTeammate][Coord] p2-plan-observed failed: " + ex.Message); }
        }

        private static bool ReadBoolMember(object obj, string name)
        {
            object value = GetMemberValue(obj, name);
            return value is bool && (bool)value;
        }

        private static long ReadLongMember(object obj, string[] names)
        {
            if (obj == null) return -1;
            for (int i = 0; i < names.Length; i++)
            {
                try
                {
                    object value = GetMemberValue(obj, names[i]);
                    if (value == null) continue;
                    return Convert.ToInt64(value);
                }
                catch { }
            }
            return -1;
        }

        private static string ReadTextMember(object obj, string[] names)
        {
            if (obj == null) return null;
            for (int i = 0; i < names.Length; i++)
            {
                object value = GetMemberValue(obj, names[i]);
                if (value != null) return value.ToString();
            }
            return null;
        }

        public static void UpdateSearchTelemetry(string source)
        {
            try
            {
                Type solverType = AccessTools.TypeByName("CombatSolver.SolverController");
                object search = null;
                if (solverType != null)
                {
                    FieldInfo searchField = AccessTools.Field(solverType, "_search");
                    if (searchField != null) search = searchField.GetValue(null);
                }
                object interaction = GetMemberValue(search, "Interaction");
                object progress = GetMemberValue(interaction, "Progress");
                object stopped = GetMemberValue(interaction, "StoppedResult");
                object result = GetMemberValue(search, "LatestResult") ?? stopped ?? GetMemberValue(progress, "CurrentBestResult");
                bool timedOut = ReadBoolMember(search, "TimedOut") || ReadBoolMember(search, "IsTimedOut") || ReadBoolMember(interaction, "TimedOut") || ReadBoolMember(interaction, "IsTimedOut") || ReadBoolMember(progress, "TimedOut") || ReadBoolMember(progress, "IsTimedOut") || ReadBoolMember(result, "TimedOut") || ReadBoolMember(result, "IsTimedOut");
                string statusText = ReadTextMember(search, new string[] { "SearchStatus", "Status", "CompletionReason", "TerminationReason" }) ?? ReadTextMember(interaction, new string[] { "SearchStatus", "Status", "CompletionReason", "TerminationReason" }) ?? ReadTextMember(result, new string[] { "SearchStatus", "Status", "CompletionReason", "TerminationReason" });
                bool searching = ReadBoolMember(search, "IsSearching") || ReadBoolMember(interaction, "IsSearching");
                if (timedOut || (!string.IsNullOrEmpty(statusText) && statusText.IndexOf("timeout", StringComparison.OrdinalIgnoreCase) >= 0)) P2SearchStatusThisTurn = "timeout";
                else if (searching) P2SearchStatusThisTurn = "searching";
                else if (result != null || stopped != null) P2SearchStatusThisTurn = "complete";
                else if (!string.IsNullOrEmpty(statusText) && statusText.IndexOf("complete", StringComparison.OrdinalIgnoreCase) >= 0) P2SearchStatusThisTurn = "complete";
                else P2SearchStatusThisTurn = "unknown";
                long nodes = ReadLongMember(progress, new string[] { "Nodes", "NodeCount", "ExpandedNodes", "ExpandedNodeCount", "NodesExpanded", "TotalNodes" });
                if (nodes < 0) nodes = ReadLongMember(interaction, new string[] { "Nodes", "NodeCount", "ExpandedNodes", "ExpandedNodeCount", "NodesExpanded", "TotalNodes" });
                if (nodes < 0) nodes = ReadLongMember(search, new string[] { "Nodes", "NodeCount", "ExpandedNodes", "ExpandedNodeCount", "NodesExpanded", "TotalNodes" });
                if (nodes >= 0) P2SearchNodesThisTurn = nodes;
            }
            catch { P2SearchStatusThisTurn = "unknown"; }
        }



        private static int ExtractCountFromPlan(object planObj)

        {

            if (planObj == null) return -1;

            try

            {

                var propCount = planObj.GetType().GetProperty("ActionCount", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);

                if (propCount != null)

                {

                    return Convert.ToInt32(propCount.GetValue(planObj));

                }

            }

            catch { }

            try

            {

                var propActions = planObj.GetType().GetProperty("Actions", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);

                if (propActions != null)

                {

                    var actionsObj = propActions.GetValue(planObj);

                    if (actionsObj is ICollection)

                    {

                        return ((ICollection)actionsObj).Count;

                    }

                    if (actionsObj is IEnumerable)

                    {

                        int c = 0;

                        foreach (var x in (IEnumerable)actionsObj) c++;

                        return c;

                    }

                }

            }

            catch { }

            return -1;

        }



        public static bool CheckEmptyPlanRecovery(CombatState state, Player player2, object[] args, ref Task resultTask)

        {

            int p2HandCount = GetPlayerHandCardCount(player2);

            int actionCount = GetPlanActionCount(args);
            if (actionCount < 0)
            {
                if (P2DeployStartActionCountThisTurn >= 0) actionCount = P2DeployStartActionCountThisTurn;
                else if (P2FullAutoActionCountThisTurn >= 0) actionCount = P2FullAutoActionCountThisTurn;
            }

            bool hasAttack;
            bool hasUsableCard = P2HasUsableCard(player2, out hasAttack);
            int energy = player2 != null && player2.PlayerCombatState != null ? player2.PlayerCombatState.Energy : 0;

            if (actionCount == 0 && (!hasUsableCard || energy <= 0))
            {
                GD.Print(string.Format("[AiTeammate][Coord] p2-zero-action-legal turn={0} reason={1} hand={2} energy={3}", TurnNumber, energy <= 0 ? "zero-energy" : "no-playable-card", p2HandCount, energy));
                P2TurnEndReason = energy <= 0 ? "zero-energy" : "no-playable-card";
                P2ZeroActionProtectionFinalizedThisTurn = true;
                return true;
            }



            if (p2HandCount > 0 && actionCount == 0 && hasUsableCard)

            {

                if (!P2ZeroActionRetryUsedThisTurn)

                {

                    P2ZeroActionRetryUsedThisTurn = true;
                    HasRetriedEmptyPlanThisTurn = true;

                    IsWaiting = false;

                    HasReleasedThisTurn = true;

                    LastReleaseTrigger = "empty-plan-retry";

                    RecalcSucceeded = false;

                    CachedDeployResult = null;



                    GD.Print(string.Format("[AiTeammate][Coord] p2-zero-action-retry turn={0} physicalHand={1} energy={2} actionCount=0", TurnNumber, p2HandCount, energy));

                    CleanHangingDeployment();

                    RequestRecalculation(state, "empty-plan-retry");

                    resultTask = Task.CompletedTask;

                    return false;

                }

                else

                {

                    GD.Print(string.Format("[AiTeammate][Coord] p2-zero-action-retry-exhausted turn={0} physicalHand={1} energy={2}, entering fallback", TurnNumber, p2HandCount, energy));
                    if (!P2FallbackGreedyUsedThisTurn && TryFallbackGreedy(player2))
                    {
                        P2TurnEndReason = "fallback-greedy";
                        resultTask = Task.CompletedTask;
                        GD.Print("[AiTeammate][Coord] p2-zero-action-fallback-greedy-enqueued turn=" + TurnNumber);
                        return false;
                    }
                    P2TurnEndReason = "fallback-failed";
                    P2ZeroActionProtectionFinalizedThisTurn = true;
                    GD.Print("[AiTeammate][Coord] p2-zero-action-fallback-failed turn=" + TurnNumber + " allowing finite failure state");

                }

            }

            return true;

        }



        public static void CacheDeploymentCall(MethodInfo method, object[] args, string source, int turn, object instance)
        {
            try
            {
                if (instance != null) CachedSolverController = instance;
                if (method == null && args != null)
                {
                    if (args.Length == 3 && StartDeploymentMethod != null) method = StartDeploymentMethod;
                    else if (args.Length == 6 && DeployCurrentTurnMethod != null) method = DeployCurrentTurnMethod;
                }
                CachedDeployMethod = method;
                CachedDeployArgs = args != null ? (object[])args.Clone() : null;
                CachedDeployMethodName = method != null ? method.Name : (args != null ? (args.Length == 3 ? "StartDeployment" : (args.Length == 6 ? "DeployCurrentTurn" : "unknown")) : "unknown");
                CachedDeployParamCount = args != null ? args.Length : 0;
                string[] types;
                if (args != null)
                {
                    types = new string[args.Length];
                    for (int i = 0; i < args.Length; i++)
                    {
                        types[i] = (args[i] != null) ? args[i].GetType().Name : "null";
                    }
                }
                else
                {
                    types = new string[0];
                }
                CachedDeployParamTypes = types;
                CachedDeploySource = source ?? "unknown";
                CachedDeployTurn = turn;

                object res = ResolveResultFromArgs(args);
                if (res != null) CachedDeployResult = res;

                string typesStr = CachedDeployParamTypes != null ? string.Join(",", CachedDeployParamTypes) : "";
                GD.Print(string.Format("[AiTeammate][Coord] deploy-args-cached method={0} params={1} types=[{2}] source={3} turn={4}",
                    CachedDeployMethodName, CachedDeployParamCount, typesStr, CachedDeploySource, CachedDeployTurn));
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] CacheDeploymentCall error: " + ex);
            }
        }

        public static void LogEndTurnButtonStateAudit(string state, string reason, string source, MegaCrit.Sts2.Core.Nodes.Combat.NEndTurnButton btn = null)
        {
            try
            {
                ulong localId = LocalContext.NetId.HasValue ? LocalContext.NetId.Value : 0;
                ulong draId = TurnFlowPatches.GetDraCurrentControlledPlayerId();
                bool p1Alive = !IsPlayer1Dead();
                bool p2Alive = !IsPlayer2Dead();

                var cm = CombatManager.Instance;
                bool actionsDisabled = (P1InputLockDepth > 0) || (cm != null && cm.PlayerActionsDisabled);
                bool isDeploying = IsDeploying;
                // Directive #5.86 (Task 1B): RecalcRequestedThisTurn is a latch that stayed true for
                // the whole turn, so the audit reported solverRecalculating=True even after P2 had
                // ended its turn. Report an *in-flight* recalculation instead: the request must still
                // be unsatisfied and P2's turn must not be settled yet.
                bool solverRecalc = PlanEmptyRecoveryInProgress || (RecalcRequestedThisTurn && !RecalcSucceeded && !IsP2TurnSettled());

                Player p1 = FlowCoordinator.GetPlayer1();
                Player p2 = FlowCoordinator.GetPlayer2();
                int p1Queue = p1 != null ? GetP2QueuePlayCardCount(p1.NetId) : 0;
                int p2Queue = p2 != null ? GetP2QueuePlayCardCount(p2.NetId) : 0;

                if (string.IsNullOrEmpty(reason) || reason == "auto")
                {
                    if (!IsPlayPhase()) reason = "non-playphase";
                    else if (isDeploying) reason = "p2-deploying";
                    else if (!p1Alive && p2Alive) reason = "p1-dead-p2-active";
                    else if (actionsDisabled) reason = "input-lock-disabled";
                    else if (solverRecalc) reason = "solver-recalculating";
                    else if (p1Queue > 0 || p2Queue > 0) reason = "queue-has-actions";
                    else if (localId != 0 && draId != 0 && localId != draId) reason = "context-mismatch";
                    else reason = "native-state-check";
                }

                string logMsg = string.Format(
                    "[AiTeammate][Coord] endturn-state-audit state={0} LocalContext={1} DRA={2} P1Alive={3} P2Alive={4} PlayerActionsDisabled={5} IsDeploying={6} solverRecalculating={7} p1Queue={8} p2Queue={9} reason={10} source={11}",
                    state ?? "unknown",
                    localId != 0 ? localId.ToString() : "none",
                    draId != 0 ? draId.ToString() : "none",
                    p1Alive,
                    p2Alive,
                    actionsDisabled,
                    isDeploying,
                    solverRecalc,
                    p1Queue,
                    p2Queue,
                    reason,
                    source ?? "unknown"
                );
                GD.Print(logMsg);
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] LogEndTurnButtonStateAudit error: " + ex);
            }
        }

        // Directive #5.97-HF1 Task 1: Re-entrancy guard & in-flight AnimIn tween tracker
        private static bool _isHealingEndTurnButton = false;
        public static DateTime LastEndTurnAnimInUtc = DateTime.MinValue;

        // Directive #5.97 Task 1 & #5.97-HF1: Self-heal NEndTurnButton if stuck at HidePos (off-screen)
        public static void HealEndTurnButtonIfMisplaced(MegaCrit.Sts2.Core.Nodes.Combat.NEndTurnButton btn, string caller)
        {
            if (_isHealingEndTurnButton) return;
            try
            {
                _isHealingEndTurnButton = true;
                if (btn == null || !GodotObject.IsInstanceValid(btn)) return;
                if (!IsInCombat() || !IsPlayPhase()) return;

                bool p1Dead = IsPlayer1Dead();
                Player p1 = FlowCoordinator.GetPlayer1();
                var cm = CombatManager.Instance;
                var cs = cm != null ? cm.DebugOnlyGetState() : null;
                bool isPlayerSide = cs != null && cs.CurrentSide == CombatSide.Player;

                if (p1Dead || p1 == null || cm == null || cm.IsPlayerReadyToEndTurn(p1) || !isPlayerSide) return;

                FieldInfo stateField = AccessTools.Field(btn.GetType(), "_state");
                PropertyInfo stateProp = AccessTools.Property(btn.GetType(), "State");
                object currentState = stateField != null ? stateField.GetValue(btn) : (stateProp != null ? stateProp.GetValue(btn, null) : null);
                int stateInt = -1;
                try { if (currentState != null) stateInt = Convert.ToInt32(currentState); } catch { }

                PropertyInfo canTurnProp = AccessTools.Property(btn.GetType(), "CanTurnBeEnded");
                object canTurnObj = canTurnProp != null ? canTurnProp.GetValue(btn, null) : null;
                bool canTurn = canTurnObj is bool && (bool)canTurnObj;

                PropertyInfo showPosProp = AccessTools.Property(btn.GetType(), "ShowPos");
                object spObj = showPosProp != null ? showPosProp.GetValue(btn, null) : null;
                Vector2 showPos = spObj is Vector2 ? (Vector2)spObj : Vector2.Zero;

                bool animInInFlight = (DateTime.UtcNow - LastEndTurnAnimInUtc).TotalMilliseconds < 650.0;
                float distToShowPos = showPos != Vector2.Zero ? (btn.Position - showPos).Length() : 0f;
                bool offscreen = !animInInFlight && showPos != Vector2.Zero && distToShowPos > 20f;
                bool isHiddenState = (stateInt == 2);
                bool shouldBeEnabled = canTurn && (stateInt != 0);
                bool visualFaded = !animInInFlight && (!btn.Visible || btn.Modulate.A < 0.9f);

                if (isHiddenState || shouldBeEnabled || offscreen || visualFaded)
                {
                    LastEndTurnAnimInUtc = DateTime.UtcNow;
                    btn.Visible = true;
                    Color mod = btn.Modulate;
                    if (mod.A < 0.9f) { mod.A = 1.0f; btn.Modulate = mod; }

                    if (stateField != null)
                    {
                        stateField.SetValue(btn, Enum.ToObject(stateField.FieldType, 2)); // State.Hidden
                    }

                    MethodInfo setStateMethod = AccessTools.Method(btn.GetType(), "SetState");
                    if (setStateMethod != null)
                    {
                        ParameterInfo[] ps = setStateMethod.GetParameters();
                        if (ps.Length > 0)
                        {
                            if (canTurn)
                            {
                                setStateMethod.Invoke(btn, new object[] { Enum.ToObject(ps[0].ParameterType, 0) }); // State.Enabled (triggers native AnimIn)
                            }
                            else
                            {
                                MethodInfo animInMethod = AccessTools.Method(btn.GetType(), "AnimIn");
                                if (animInMethod != null) animInMethod.Invoke(btn, null);
                                setStateMethod.Invoke(btn, new object[] { Enum.ToObject(ps[0].ParameterType, 1) }); // State.Disabled
                            }
                        }
                    }
                    string stateStr = stateField != null ? (stateField.GetValue(btn) ?? "unknown").ToString() : (stateProp != null ? (stateProp.GetValue(btn, null) ?? "unknown").ToString() : "unknown");
                    GD.Print(string.Format("[AiTeammate][Coord] endturn-button-refresh-anim-healed caller={0} state={1} pos={2} showPos={3}", caller, stateStr, btn.Position, showPos));
                }
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] HealEndTurnButtonIfMisplaced error: " + ex.Message);
            }
            finally
            {
                _isHealingEndTurnButton = false;
            }
        }

        public static bool CheckDeadP1ZeroProgressFallback(string source)
        {
            try
            {
                if (!IsInCombat() || !IsPlayPhase()) return false;
                if (AreAllPlayersDead() || IsTerminalCombatFinalized) return false;

                if (!IsPlayer1Dead()) return false;
                Player p2 = FlowCoordinator.GetPlayer2();
                if (p2 == null || p2.Creature == null || !p2.Creature.IsAlive) return false;

                if (IsPlayer2ActionInFlight()) return false;
                if (GetP2QueuePlayCardCount(p2.NetId) > 0) return false;
                if (P2PendingChoiceCount > 0 || FlowCoordinator.HasPendingP2Choice(p2) || IsPlayer1InChoiceScreen()) return false;

                var cm = CombatManager.Instance;
                if (cm != null && cm.IsPlayerReadyToEndTurn(p2)) return false;

                GD.Print(string.Format("[AiTeammate][Coord] dead-p1-zero-progress-check source={0} turn={1} p2={2}", source, TurnNumber, p2.NetId));

                int energy = (p2.PlayerCombatState != null) ? p2.PlayerCombatState.Energy : 0;
                bool hasAtk;
                bool hasUsable = P2HasUsableCard(p2, out hasAtk);

                if (energy > 0 && hasUsable && !P2FallbackGreedyUsedThisTurn)
                {
                    GD.Print(string.Format("[AiTeammate][Coord] dead-p1-zero-progress fallback=greedy turn={0}", TurnNumber));
                    bool enqueued = TryFallbackGreedy(p2);
                    if (enqueued) return true;
                }

                GD.Print(string.Format("[AiTeammate][Coord] dead-p1-zero-progress fallback=endturn turn={0} source={1}", TurnNumber, source));
                P2FallbackExhaustedThisTurn = true;
                LogFallbackExhaustedSet("dead-p1-zero-progress");
                PlanEmptyRecoveryInProgress = false;
                return EnqueueP2EndTurn(p2);
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] CheckDeadP1ZeroProgressFallback exception: " + ex);
                return false;
            }
        }

        public static void RequestRecalculation(CombatState state, string trigger)

        {

            try

            {

                if (trigger != null && trigger.StartsWith("midturn-replan"))

                {

                    // Directive #3.9.4: Midturn replans are allowed up to 2 times per turn

                }

                else if (RecalcRequestedThisTurn && 
                    trigger != "empty-plan-retry" && 
                    trigger != "plan-empty-retry" && 
                    trigger != "deploy-hook-missed-recovery" && 
                    trigger != "enemy-already-debuffed" && 
                    trigger != "lifeline-cards-affordable" && 
                    trigger != "p1-dead-recovery" && 
                    !(trigger != null && trigger.StartsWith("solver-early-end", StringComparison.OrdinalIgnoreCase) && !HasRetriedSolverEarlyEndThisTurn))

                {

                    GD.Print("[AiTeammate][Coord] RequestRecalculation blocked: already requested once this turn (trigger=" + trigger + ")");

                    if (IsPlayer1Dead())
                    {
                        CheckDeadP1ZeroProgressFallback("recalc-blocked-dead-p1");
                    }
                    else
                    {
                        Player p2Player = FlowCoordinator.GetPlayer2();
                        ulong p2NetId = (p2Player != null) ? p2Player.NetId : 0;
                        bool hasQueuedCards = (p2NetId != 0 && GetP2QueuePlayCardCount(p2NetId) > 0);
                        if (P2FallbackGreedyUsedThisTurn || P2FallbackExecutedThisTurn || HasCompletedDeploymentThisTurn || hasQueuedCards)
                        {
                            GD.Print(string.Format("[AiTeammate][Coord] TriggerCachedDeployment skipped: fallback or deployment active (fallbackGreedy={0} fallbackExecuted={1} completedDeploy={2} queuedCards={3})",
                                P2FallbackGreedyUsedThisTurn, P2FallbackExecutedThisTurn, HasCompletedDeploymentThisTurn, hasQueuedCards));
                        }
                        else
                        {
                            TriggerCachedDeployment();
                        }
                    }

                    return;

                }

                RecalcRequestedThisTurn = true;

                if (trigger != null && trigger.StartsWith("solver-early-end", StringComparison.OrdinalIgnoreCase)) HasRetriedSolverEarlyEndThisTurn = true;

                if (trigger == "empty-plan-retry")

                {

                    CachedDeployResult = null;

                }



                CurrentRecalcGeneration++;

                ReleaseRequestedTime = DateTime.UtcNow;

                RecalcSucceeded = false;

                Watchdog3sFired = false;



                // 1. Reset all solver state: unfreeze route, resume auto, cancel search CTS, cancel deferred, cancel deployment

                ResetSolverStateBeforeSearch();

                // Directive #5.91 T1: enforce the CombatSolver per-layer time budget before every search.
                EnsureOptimalCombatSolverSettings();



                // Directive #5.90 T1.3: a freshly requested search must not be mistaken for a finished
                // deployment. ResetTurnState("OnEndedTurnLocally") sets HasCompletedDeploymentThisTurn=true
                // mid-round, so without this reset the new search was killed on its very first tick with
                // staleReason=deployment-already-completed.
                HasCompletedDeploymentThisTurn = false;
                SolverEarlyEndReportedThisTurn = false;

                // Directive #5.90 T1.3: CombatSolver rejects a search started while the game still has
                // PlayerActionsDisabled ("SEARCH_REJECT reason=玩家操作当前被游戏禁用"). Recalculations
                // were requested from inside DeployCurrentTurn, where actions are disabled.
                try
                {
                    var cmReenable = CombatManager.Instance;
                    if (cmReenable != null && cmReenable.PlayerActionsDisabled && P1InputLockDepth <= 0 && !IsDeploying)
                    {
                        TurnFlowPatches.SetPlayerActionsDisabled(cmReenable, false);
                        GD.Print("[AiTeammate][Coord] recalc-actions-reenabled trigger=" + trigger + " turn=" + TurnNumber);
                    }
                }
                catch { }



                // 2. Ensure FullAuto is enabled so new results auto-deploy

                EnsureFullAutoEnabled();



                // 3. Obtain SolverController instance

                var controller = CachedSolverController;

                if (controller == null)

                {

                    var solverType = AccessTools.TypeByName("CombatSolver.SolverController");

                    if (solverType != null)

                    {

                        var instProp = AccessTools.Property(solverType, "Instance");

                        if (instProp != null)

                        {

                            controller = instProp.GetValue(null);

                            CachedSolverController = controller;

                        }

                    }

                }



                if (state == null)

                {

                    var cm = CombatManager.Instance;

                    if (cm != null)

                    {

                        state = cm.DebugOnlyGetState();

                    }

                }



                GD.Print("[AiTeammate][Coord] recalc-requested trigger=" + trigger + " time=" + ReleaseRequestedTime.ToString("HH:mm:ss.fff"));

                if (!InvokeLiveRequestSearch(state, trigger))

                {

                    GD.PrintErr(string.Format("[AiTeammate][Coord] Cannot request recalculation: state={0}; falling back to cached deploy.", state == null));

                    if (IsPlayer1Dead())
                    {
                        CheckDeadP1ZeroProgressFallback("recalc-failed-dead-p1");
                    }
                    else
                    {
                        TriggerCachedDeployment();
                    }

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] RequestRecalculation exception, fail-open to cached deploy: " + ex);

                if (IsPlayer1Dead())
                {
                    CheckDeadP1ZeroProgressFallback("recalc-exception-dead-p1");
                }
                else
                {
                    TriggerCachedDeployment();
                }

            }

        }



        public static void ReleaseWait(string trigger)

        {

            if (!IsWaiting) return;

            IsWaiting = false;

            HasReleasedThisTurn = true;

            LastReleaseTrigger = trigger;

            GD.Print("[AiTeammate][Coord] Release trigger fired: trigger=" + trigger);



            var cm = CombatManager.Instance;

            var state = cm != null ? cm.DebugOnlyGetState() : null;



            if (!RecalcRequestedThisTurn)

            {

                RequestRecalculation(state, trigger);

            }

            else

            {

                GD.Print("[AiTeammate][Coord] Recalculation already requested this turn, deploying plan for trigger=" + trigger);

                TriggerCachedDeployment();

            }

        }



        public static void TriggerCachedDeployment()

        {

            try

            {

                MethodInfo targetMethod = CachedDeployMethod;

                object[] targetArgs = CachedDeployArgs;

                object targetInstance = (targetMethod != null && targetMethod.IsStatic) ? null : CachedSolverController;



                bool isValid = false;

                if (targetMethod != null && targetArgs != null)

                {

                    ParameterInfo[] parameters = targetMethod.GetParameters();

                    if (parameters.Length == targetArgs.Length)

                    {

                        bool typesMatch = true;

                        for (int i = 0; i < parameters.Length; i++)

                        {

                            if (targetArgs[i] != null && !parameters[i].ParameterType.IsAssignableFrom(targetArgs[i].GetType()))

                            {

                                typesMatch = false;

                                break;

                            }

                        }

                        if (typesMatch) isValid = true;

                    }

                }



                if (isValid)

                {

                    IsDeploying = true;

                    DeployStartTime = DateTime.UtcNow;

                    GD.Print("[AiTeammate][Coord] Invoking " + targetMethod.Name + " (" + targetArgs.Length + " params) on cached SolverController with verified cached args.");

                    var res = targetMethod.Invoke(targetInstance, targetArgs);

                    var task = res as Task;

                    if (task != null) MegaCrit.Sts2.Core.Helpers.TaskHelper.RunSafely(task);

                    return;

                }



                int expectedCount = targetMethod != null ? targetMethod.GetParameters().Length : -1;

                int actualCount = targetArgs != null ? targetArgs.Length : -1;

                GD.PrintErr("[AiTeammate][Coord] Cannot trigger cached deployment: parameter count mismatch (method expects " + expectedCount + ", cached args " + (actualCount >= 0 ? actualCount.ToString() : "null") + ")!");



                CombatState combatState = null;

                if (targetArgs != null) combatState = ResolveStateFromArgs(targetArgs);

                if (combatState == null && CombatManager.Instance != null) combatState = CombatManager.Instance.DebugOnlyGetState();



                object solverResult = CachedDeployResult;

                if (solverResult == null && targetArgs != null) solverResult = ResolveResultFromArgs(targetArgs);



                object host = (targetArgs != null && targetArgs.Length > 0 && targetArgs[0] is MegaCrit.Sts2.Core.Nodes.NGame)

                    ? targetArgs[0]

                    : (MegaCrit.Sts2.Core.Nodes.NGame.Instance ?? (object)CombatManager.Instance);



                MethodInfo reconMethod = StartDeploymentMethod ?? StartFullAutoDeploymentMethod;

                if (reconMethod != null && host != null && combatState != null && solverResult != null)

                {

                    ParameterInfo[] rParams = reconMethod.GetParameters();

                    if (rParams.Length == 3)

                    {

                        object[] reconstructedArgs = new object[] { host, combatState, solverResult };

                        IsDeploying = true;

                        DeployStartTime = DateTime.UtcNow;

                        GD.Print("[AiTeammate][Coord] deploy-args-reconstructed method=" + reconMethod.Name + " params=3 source=reconstruct turn=" + TurnNumber);

                        var res = reconMethod.Invoke(reconMethod.IsStatic ? null : CachedSolverController, reconstructedArgs);

                        var task = res as Task;

                        if (task != null) MegaCrit.Sts2.Core.Helpers.TaskHelper.RunSafely(task);

                        return;

                    }

                }



                GD.PrintErr("[AiTeammate][Coord] deploy-args-recovery-failed reason=cannot-reconstruct turn=" + TurnNumber);

                if (IsPlayer1Dead())

                {

                    CheckDeadP1ZeroProgressFallback("deploy-reconstruction-failed");

                }

                else

                {

                    TurnFlowPatches.RestorePlayer1ControlIfActive("wakuu-coord-failopen");

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] TriggerCachedDeployment error: " + ex);

                if (IsPlayer1Dead())

                {

                    CheckDeadP1ZeroProgressFallback("deploy-exception-failopen");

                }

                else

                {

                    try { TurnFlowPatches.RestorePlayer1ControlIfActive("wakuu-coord-failopen"); } catch { }

                }

            }

        }



        public static void CheckTriggers(string sourceContext)

        {

            if (!IsWaiting) return;



            try

            {

                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null || state.Players == null || state.Players.Count < 2) return;



                var player1 = state.Players[0];

                var player2 = state.Players[state.Players.Count - 1];



                // Directive #3.9.2: Joint Lethal Push trigger

                string lethalInfo;

                if (CheckJointLethalPush(state, player1, player2, out lethalInfo))

                {

                    ReleaseWait("joint-lethal-push");

                    return;

                }



                // a. Enemy Harmful Status: Any living enemy acquires harmful status (Vulnerable, Weak, Frail, Poison, Strength Down, etc.)

                if (HasEnemyHarmfulStatus(state))

                {

                    ReleaseWait("enemy-debuffed");

                    return;

                }



                // b. Ally Buff / Resource Received: Player 2 receives Strength, Block, Energy, or Draw from teammate

                if (HasP2ReceivedBuffOrResources(state, player2))

                {

                    ReleaseWait("p2-buff-received");

                    return;

                }



                // Dynamic inspection of cheapest team setup card currently in Player 1's hand

                int currentCheapestDebuff = int.MaxValue;

                bool p1HasDebuffInHand = false;

                if (player1 != null && player1.PlayerCombatState != null && player1.PlayerCombatState.Hand != null)

                {

                    var handCards = player1.PlayerCombatState.Hand.Cards;

                    if (handCards != null)

                    {

                        foreach (var c in handCards)

                        {

                            string sType;

                            if (c != null && CheckIsPlayable(c) && CardIsTeamSetup(c, out sType))

                            {

                                p1HasDebuffInHand = true;

                                int cCost = GetCardEnergyCost(c);

                                if (cCost < currentCheapestDebuff)

                                {

                                    currentCheapestDebuff = cCost;

                                }

                            }

                        }

                    }

                }

                if (currentCheapestDebuff != int.MaxValue)

                {

                    CheapestP1DebuffCost = currentCheapestDebuff;

                }



                // c. Player 1 Energy Insufficient: remaining energy < cheapest setup card in P1 hand

                if (player1 != null && player1.PlayerCombatState != null)

                {

                    int currentEnergy = player1.PlayerCombatState.Energy;

                    if (p1HasDebuffInHand && currentCheapestDebuff != int.MaxValue && currentEnergy < currentCheapestDebuff)

                    {

                        ReleaseWait("p1-energy-insufficient");

                        return;

                    }

                }



                // e. Re-evaluation Unmet: re-evaluating 3 wait conditions shows they are no longer simultaneously satisfied

                string reason;

                var decision = EvaluateDecision(cm, state, player1, player2, out reason);

                if (decision != CoordinatorDecision.Wait)

                {

                    ReleaseWait("re-evaluation-unmet");

                    return;

                }

            }

            catch (Exception ex)

            {

                // Fail-open guarantee: on error in trigger inspection, release wait immediately!

                GD.PrintErr("[AiTeammate][Coord] CheckTriggers exception, releasing wait fail-open: " + ex);

                ReleaseWait("re-evaluation-unmet");

            }

        }



        // Directive #5.16 T1: Solver state getters and Mid-deployment / Search watchdog

        public static bool IsSolverDeploying()

        {

            try

            {

                if (IsDeployingGetter == null)

                {

                    var sc = AccessTools.TypeByName("CombatSolver.SolverController");

                    if (sc != null)

                    {

                        IsDeployingGetter = AccessTools.PropertyGetter(sc, "IsDeploying");

                    }

                }

                if (IsDeployingGetter != null)

                {

                    return (bool)IsDeployingGetter.Invoke(null, null);

                }

                if (DeploymentField != null)

                {

                    return DeploymentField.GetValue(null) != null;

                }

            }

            catch { }

            return IsDeploying;

        }



        public static bool IsSolverSearching()

        {

            try

            {

                if (IsSearchingGetter == null)

                {

                    var sc = AccessTools.TypeByName("CombatSolver.SolverController");

                    if (sc != null)

                    {

                        IsSearchingGetter = AccessTools.PropertyGetter(sc, "IsSearching");

                    }

                }

                if (IsSearchingGetter != null)

                {

                    return (bool)IsSearchingGetter.Invoke(null, null);

                }

            }

            catch { }

            return false;

        }



        public static void CheckMidDeploymentAndSearchWatchdog(DateTime now)

        {

            if (IsPreCombatOrLoading || TurnStartTime == DateTime.MinValue) return;



            var cm = CombatManager.Instance;

            var state = cm != null ? cm.DebugOnlyGetState() : null;

            if (state == null) return;



            Player player2 = null;

            if (state.Players != null && state.Players.Count > 1)

            {

                player2 = state.Players[state.Players.Count - 1];

            }

            if (player2 == null || player2.Creature == null || !player2.Creature.IsAlive)

            {

                return;

            }



            // 1. Mid-deployment watchdog

            bool isDeploying = IsSolverDeploying() || IsDeploying;

            if (isDeploying)

            {

                if (MidDeployStartTime == DateTime.MinValue)

                {

                    MidDeployStartTime = now;

                    MidDeployHangTimeoutTriggered = false;

                    MidDeployHangCriticalTriggered = false;

                }



                double elapsed = (now - MidDeployStartTime).TotalSeconds;



                // > 20s check: cancel deployment and trigger recalc

                if (elapsed > 20.0 && !MidDeployHangTimeoutTriggered)

                {

                    MidDeployHangTimeoutTriggered = true;

                    GD.PrintErr(string.Format("[AiTeammate][Coord] deploy-hang-timeout: deployment hung for {0:F1}s, cancelling deployment and triggering recalc", elapsed));

                    try

                    {

                        if (CancelDeploymentMethod != null)

                        {

                            CancelDeploymentMethod.Invoke(null, null);

                        }

                        IsDeploying = false;

                        CleanHangingDeployment();

                    }

                    catch (Exception ex)

                    {

                        GD.PrintErr("[AiTeammate][Coord] deploy-hang-timeout cancel exception: " + ex);

                    }



                    RequestRecalculation(state, "deploy-hang-timeout");

                }



                // > 35s check: escalate to CRITICAL force-end-turn path

                if (elapsed > 35.0 && !MidDeployHangCriticalTriggered)

                {

                    MidDeployHangCriticalTriggered = true;

                    GD.PrintErr("[AiTeammate][Coord] CRITICAL deploy-hang: >35s elapsed without deployment completion, forcing EndTurn for Player 2");

                    try

                    {

                        ForceEndTurnForPlayer2(cm, state, player2);

                    }

                    catch (Exception ex)

                    {

                        GD.PrintErr("[AiTeammate][Coord] CRITICAL deploy-hang force-end-turn exception: " + ex);

                    }

                }

            }

            else

            {

                MidDeployStartTime = DateTime.MinValue;

                MidDeployHangTimeoutTriggered = false;

                MidDeployHangCriticalTriggered = false;

            }



            // 2. Search alive heartbeat

            bool isSearching = IsSolverSearching();

            if (isSearching)

            {

                ArmIndependentSearchHeartbeat("process-tick-search-detected");

                if (SearchAliveStartTime == DateTime.MinValue)

                {

                    SearchAliveStartTime = now;

                    LastSearchHeartbeatTime = now;

                }



                if ((now - LastSearchHeartbeatTime).TotalSeconds >= 5.0)

                {

                    LastSearchHeartbeatTime = now;

                    double searchElapsed = (now - SearchAliveStartTime).TotalSeconds;

                    GD.Print(string.Format("[AiTeammate][Coord] search-alive: elapsed={0:F1}s search thread alive", searchElapsed));
                    RecordIndependentSearchHeartbeat(now, "process-tick");

                }

            }

            else

            {

                SearchAliveStartTime = DateTime.MinValue;

                LastSearchHeartbeatTime = DateTime.MinValue;
                DisarmIndependentSearchHeartbeat("search-inactive");

            }

        }



        public static void CheckSolverStallWatchdog(DateTime now)
        {
            if (IsPreCombatOrLoading || TurnStartTime == DateTime.MinValue) return;
            if (HasCompletedDeploymentThisTurn) return;
            if (IsDeploying) return;

            // Directive #5.34 T0.4: 放行手动流程
            if (!IsFullAutoEnabled() || !FlowCoordinator.AutoCardRewardEnabled)
            {
                return;
            }

            var cm = CombatManager.Instance;
            var state = cm != null ? cm.DebugOnlyGetState() : null;
            if (state == null) return;

            Player player2 = null;
            if (state.Players != null && state.Players.Count > 1)
            {
                player2 = state.Players[state.Players.Count - 1];
            }
            if (player2 == null || player2.Creature == null || !player2.Creature.IsAlive)
            {
                return;
            }

            try
            {
                bool anyHostileAlive = false;
                var creatures = state.Creatures;
                if (creatures != null)
                {
                    foreach (var c in creatures)
                    {
                        if (c != null && c.IsMonster && c.IsAlive)
                        {
                            anyHostileAlive = true;
                            break;
                        }
                    }
                }
                if (!anyHostileAlive) return;
            }
            catch { }

            // Directive #5.39 Task 3: Level 1 - > 12s elapsed OR >= 2.5s with solver already dead/stopped
            if (!StallRecalcTriggered)
            {
                bool timeStall = (now - TurnStartTime).TotalSeconds > 12.0;
                bool fastStall = (now - TurnStartTime).TotalSeconds >= 2.5 && !IsSolverSearching() && !IsSolverDeploying() && !P2DeployHookObservedThisTurn;
                if (timeStall || fastStall)
                {
                    StallRecalcTriggered = true;
                    StallRecalcTime = now;
                    string reason = fastStall ? "solver-search-aborted" : "solver-search-stall";
                    GD.Print(string.Format("[AiTeammate][Coord] {0}: elapsed={1:F1}s without deployment, kicking recalculation (once-per-turn)", reason, (now - TurnStartTime).TotalSeconds));
                    KickSolverRecalculation(state, reason);
                }
                return;
            }

            // Directive #5.39 Task 3: Level 2 - >= 8s after stall recalc OR >= 1.5s with solver already stopped
            if (!StallForceEndTurnTriggered)
            {
                bool timeStall2 = (now - StallRecalcTime).TotalSeconds >= 8.0;
                bool fastStall2 = (now - StallRecalcTime).TotalSeconds >= 1.5 && !IsSolverSearching() && !IsSolverDeploying();
                if (timeStall2 || fastStall2)
                {
                    StallForceEndTurnTriggered = true;
                    string reason2 = fastStall2 ? "solver-recalc-aborted" : "solver-recalc-stall";
                    GD.Print(string.Format("[AiTeammate][Coord] {0}: elapsed={1:F1}s after recalc without deployment, attempting fallback", reason2, (now - StallRecalcTime).TotalSeconds));
                    if (TryDeployCheckpointOrInterimPlan(cm, state, player2))
                    {
                        GD.Print("[AiTeammate][Coord] solver-search-stall: cached-plan deployed successfully");
                        return;
                    }

                    bool hasAttack;
                    if (P2HasUsableCard(player2, out hasAttack))
                    {
                        TryFallbackGreedy(player2);
                    }

                    if (cm != null && !cm.IsPlayerReadyToEndTurn(player2))
                    {
                        if (!EnqueueP2EndTurn(player2) || !cm.IsPlayerReadyToEndTurn(player2))
                        {
                            GD.PrintErr("[AiTeammate][Coord] CRITICAL solver-dead: fallback did not end turn, force-ending P2 turn");
                            TryInvokeResetCore();
                            ForceEndTurnForPlayer2(cm, state, player2);
                        }
                    }
                }
            }
        }

        public static object GetMemberValue(object obj, string name)

        {

            if (obj == null || string.IsNullOrEmpty(name)) return null;

            try

            {

                var t = obj.GetType();

                var prop = AccessTools.Property(t, name);

                if (prop != null) return prop.GetValue(obj, null);

                var field = AccessTools.Field(t, name) ?? AccessTools.Field(t, "<" + name + ">k__BackingField");

                if (field != null) return field.GetValue(obj);

            }

            catch { }

            return null;

        }



        public static int GetSolverResultActionCount(object solverResult)

        {

            if (solverResult == null) return 0;

            try

            {

                object actionsObj = null;

                var bestNode = GetMemberValue(solverResult, "BestNode");

                if (bestNode != null)

                {

                    actionsObj = GetMemberValue(bestNode, "Actions");

                }

                if (actionsObj == null)

                {

                    actionsObj = GetMemberValue(solverResult, "Actions") ?? GetMemberValue(solverResult, "Plan");

                }

                var col = actionsObj as System.Collections.ICollection;

                if (col != null) return col.Count;

                var enumerable = actionsObj as System.Collections.IEnumerable;

                if (enumerable != null)

                {

                    int c = 0;

                    foreach (var item in enumerable) c++;

                    return c;

                }

            }

            catch { }

            return 0;

        }



        public static bool TryDeployCheckpointOrInterimPlan(CombatManager cm, CombatState state, Player player2)

        {

            try

            {

                var solverType = AccessTools.TypeByName("CombatSolver.SolverController");

                if (solverType == null) return false;



                object candidateResult = null;

                string candidateSource = null;

                int actionCount = 0;



                // 1. Inspect _combat.LatestResult and _combat.ContinuationSource

                if (CombatField == null)

                {

                    CombatField = AccessTools.Field(solverType, "_combat");

                }

                object combatObj = CombatField != null ? CombatField.GetValue(null) : null;

                if (combatObj != null)

                {

                    var latest = GetMemberValue(combatObj, "LatestResult");

                    int cnt = GetSolverResultActionCount(latest);

                    if (cnt > 0)

                    {

                        candidateResult = latest;

                        candidateSource = "combat.LatestResult";

                        actionCount = cnt;

                    }

                    else

                    {

                        var cont = GetMemberValue(combatObj, "ContinuationSource");

                        cnt = GetSolverResultActionCount(cont);

                        if (cnt > 0)

                        {

                            candidateResult = cont;

                            candidateSource = "combat.ContinuationSource";

                            actionCount = cnt;

                        }

                    }

                }



                // 2. Inspect _search.Interaction.Progress.CurrentBestResult and _search.Interaction.StoppedResult

                if (candidateResult == null)

                {

                    var searchField = AccessTools.Field(solverType, "_search");

                    object searchObj = searchField != null ? searchField.GetValue(null) : null;

                    if (searchObj != null)

                    {

                        var interactionObj = GetMemberValue(searchObj, "Interaction");

                        if (interactionObj != null)

                        {

                            var progressObj = GetMemberValue(interactionObj, "Progress");

                            if (progressObj != null)

                            {

                                var curBest = GetMemberValue(progressObj, "CurrentBestResult");

                                int cnt = GetSolverResultActionCount(curBest);

                                if (cnt > 0)

                                {

                                    candidateResult = curBest;

                                    candidateSource = "search.CurrentBestResult";

                                    actionCount = cnt;

                                }

                            }

                            if (candidateResult == null)

                            {

                                var stopped = GetMemberValue(interactionObj, "StoppedResult");

                                int cnt = GetSolverResultActionCount(stopped);

                                if (cnt > 0)

                                {

                                    candidateResult = stopped;

                                    candidateSource = "search.StoppedResult";

                                    actionCount = cnt;

                                }

                            }

                        }

                    }

                }



                // 3. Inspect LastCompletedResultForTesting on SolverController

                if (candidateResult == null)

                {

                    var lastTestingField = AccessTools.Field(solverType, "<LastCompletedResultForTesting>k__BackingField")

                        ?? AccessTools.Field(solverType, "_lastCompletedResultForTesting");

                    if (lastTestingField != null)

                    {

                        var lastTesting = lastTestingField.GetValue(null);

                        int cnt = GetSolverResultActionCount(lastTesting);

                        if (cnt > 0)

                        {

                            candidateResult = lastTesting;

                            candidateSource = "LastCompletedResultForTesting";

                            actionCount = cnt;

                        }

                    }

                }



                if (candidateResult == null || actionCount <= 0)

                {

                    return false;

                }



                // Find StartDeployment or StartFullAutoDeployment

                MethodInfo deployMethod = AccessTools.Method(solverType, "StartDeployment")

                    ?? AccessTools.Method(solverType, "StartFullAutoDeployment");

                if (deployMethod == null)

                {

                    return false;

                }



                var controller = CachedSolverController;

                var pars = deployMethod.GetParameters();

                object[] invokeArgs = new object[pars.Length];

                for (int i = 0; i < pars.Length; i++)

                {

                    var pType = pars[i].ParameterType;

                    if (pType.IsAssignableFrom(typeof(CombatState)) || pType.Name.Contains("CombatState"))

                    {

                        invokeArgs[i] = state;

                    }

                    else if (pType.IsAssignableFrom(candidateResult.GetType()) || pType.Name.Contains("SolverResult"))

                    {

                        invokeArgs[i] = candidateResult;

                    }

                    else if (typeof(Godot.Node).IsAssignableFrom(pType))

                    {

                        // Same type-identity fix as the kick path: take the instance through the

                        // parameter's own type (CombatSolver may carry a second sts2 type copy).

                        object hostInst = null;

                        try

                        {

                            var instProp = pType.GetProperty("Instance", BindingFlags.Public | BindingFlags.Static);

                            if (instProp != null) hostInst = instProp.GetValue(null, null);

                        }

                        catch { }

                        if (hostInst == null)

                        {

                            try { hostInst = MegaCrit.Sts2.Core.Nodes.NGame.Instance; } catch { }

                        }

                        invokeArgs[i] = hostInst ?? (object)cm;

                    }

                    else

                    {

                        invokeArgs[i] = null;

                    }

                }



                GD.Print("[AiTeammate][Coord] CRITICAL recovery-tier=checkpoint-deploy source=" + candidateSource + " actions=" + actionCount);

                HasReleasedThisTurn = true;

                LastReleaseTrigger = "checkpoint-deploy";

                IsDeploying = true;

                DeployStartTime = DateTime.UtcNow;

                Watchdog3sFired = false;



                if (player2 != null)

                {

                    TurnFlowPatches.SwitchControlToPlayer(player2.NetId, "wakuu-checkpoint-deploy", true);

                    TurnFlowPatches.SetPlayerActionsDisabled(cm, true);

                }



                object resTaskObj = deployMethod.Invoke(deployMethod.IsStatic ? null : controller, invokeArgs);

                var task = resTaskObj as Task;

                if (task != null)

                {

                    MegaCrit.Sts2.Core.Helpers.TaskHelper.RunSafely(task);

                }

                return true;

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] TryDeployCheckpointOrInterimPlan error: " + ex);

                return false;

            }

        }



        // Directive #5.47: P2 Potion continuation & force-end protection
        public static string ExtractPotionIdFromAction(MegaCrit.Sts2.Core.GameActions.UsePotionAction action)
        {
            if (action == null) return "unknown";
            try
            {
                string str = action.ToString();
                if (!string.IsNullOrEmpty(str))
                {
                    int potIdx = str.IndexOf("POTION.");
                    if (potIdx >= 0)
                    {
                        int endIdx = str.IndexOf(' ', potIdx);
                        if (endIdx > potIdx) return str.Substring(potIdx, endIdx - potIdx);
                        return str.Substring(potIdx);
                    }
                }
                Player p = action.Player ?? FlowCoordinator.GetPlayer2();
                if (p != null && p.PotionSlots != null)
                {
                    int idx = (int)action.PotionIndex;
                    if (idx >= 0 && idx < p.PotionSlots.Count)
                    {
                        var pot = p.PotionSlots[idx];
                        if (pot != null && pot.Id != null)
                        {
                            return pot.Id.ToString();
                        }
                    }
                }
            }
            catch { }
            return "unknown";
        }

        // Directive #5.48 Priority 4: Accurate potion completion handler observing actual Task/action terminal state
        public static void HandlePotionActionCompleted(MegaCrit.Sts2.Core.GameActions.UsePotionAction action, string status, Exception ex)
        {
            try
            {
                if (action == null) return;
                ulong p2NetId = GetPlayer2NetId();
                if (action.OwnerId != p2NetId) return;

                string dedupMarker = string.Format("turn={0}|action={1}", TurnNumber, action.Id);
                if (LastHandledPotionActionId == (ulong)action.Id && LastPotionContinuationMarker == dedupMarker)
                {
                    return; // Deduplicated
                }
                LastHandledPotionActionId = (ulong)action.Id;
                LastPotionContinuationMarker = dedupMarker;

                if (P2PotionOpInFlightCount > 0) P2PotionOpInFlightCount--;
                ActivePotionId = null;
                ActivePotionResolvedCard = null;

                Player p2 = FlowCoordinator.GetPlayer2();
                if (p2 == null) return;

                if (status == "completed")
                {
                    var handCards = p2.PlayerCombatState != null && p2.PlayerCombatState.Hand != null ? p2.PlayerCombatState.Hand.Cards : null;
                    int hand = handCards != null ? handCards.Count : 0;
                    int energy = p2.PlayerCombatState != null ? p2.PlayerCombatState.Energy : 0;
                    GD.Print(string.Format("[AiTeammate][Coord] p2-potion-effect-complete owner=P2 hand={0} energy={1} actionId={2}", hand, energy, action.Id));
                    ScheduleP2PotionContinuation(p2, action.Id.ToString());
                }
                else
                {
                    GD.Print(string.Format("[AiTeammate][Coord] p2-potion-action-{0} actionId={1} owner=P2 reason={2}",
                        status, action.Id, ex != null ? ex.Message : "canceled"));
                    PendingPotionContinuation = false;
                    PotionContinuationScheduled = false;
                }
            }
            catch (Exception ex2)
            {
                GD.PrintErr("[AiTeammate][Coord] HandlePotionActionCompleted error: " + ex2);
            }
        }

        public static void OnP2PotionEffectComplete(MegaCrit.Sts2.Core.GameActions.UsePotionAction action)
        {
            HandlePotionActionCompleted(action, "completed", null);
        }

        public static void CheckPotionContinuation(string source)
        {
            try
            {
                if (!PendingPotionContinuation) return;
                if (!IsInCombat() || !IsPlayPhase())
                {
                    PendingPotionContinuation = false;
                    PotionContinuationScheduled = false;
                    return;
                }

                if (PotionContinuationScheduled)
                {
                    return;
                }

                PotionContinuationScheduled = true;
                Callable.From(delegate {
                    ExecuteP2PotionContinuation();
                }).CallDeferred();
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] CheckPotionContinuation exception: " + ex);
                PotionContinuationScheduled = false;
            }
        }

        public static void ScheduleP2PotionContinuation(Player p2, string potionId)
        {
            try
            {
                if (p2 == null || !IsInCombat() || !IsPlayPhase()) return;

                if (PotionContinuationScheduled)
                {
                    GD.Print("[AiTeammate][Coord] p2-potion-continuation-scheduled=false reason=already-scheduled");
                    return;
                }

                string potMarker = string.Format("turn={0}|potion={1}", TurnNumber, potionId ?? "unknown");
                if (LastPotionContinuationMarker == potMarker)
                {
                    GD.Print("[AiTeammate][Coord] p2-potion-continuation already scheduled for " + potMarker);
                    return;
                }
                LastPotionContinuationMarker = potMarker;
                PendingPotionContinuation = true;
                PotionContinuationTurn = TurnNumber;
                PotionContinuationRequestTime = DateTime.UtcNow;
                PotionContinuationRetryCount = 0;
                PotionContinuationScheduled = true;
                HasTriggeredPotionContinuationThisTurn = true;
                PotionContinuationExecutedPlayThisTurn = false;
                PotionContinuationDeployedThisTurn = false;

                // Dispatch to Godot main thread via CallDeferred
                Callable.From(delegate {
                    ExecuteP2PotionContinuation();
                }).CallDeferred();
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] ScheduleP2PotionContinuation exception: " + ex);
                PotionContinuationScheduled = false;
            }
        }

        public static void ExecuteP2PotionContinuation()
        {
            try
            {
                if (!IsInCombat() || !IsPlayPhase())
                {
                    PendingPotionContinuation = false;
                    PotionContinuationScheduled = false;
                    return;
                }

                Player p2 = FlowCoordinator.GetPlayer2();
                var cm = CombatManager.Instance;
                var state = cm != null ? cm.DebugOnlyGetState() : null;
                if (p2 == null || state == null)
                {
                    PendingPotionContinuation = false;
                    PotionContinuationScheduled = false;
                    return;
                }

                PotionContinuationRetryCount++;
                DateTime now = DateTime.UtcNow;
                double elapsedSeconds = (now - PotionContinuationRequestTime).TotalSeconds;

                if (PotionContinuationRetryCount > MaxPotionContinuationRetries || elapsedSeconds > MaxPotionContinuationSeconds)
                {
                    PendingPotionContinuation = false;
                    PotionContinuationScheduled = false;
                    PotionContinuationExecutedPlayThisTurn = true;
                    GD.Print(string.Format("[AiTeammate][Coord] p2-potion-continuation-aborted reason=retry-budget-exhausted attempt={0}", PotionContinuationRetryCount));

                    bool hasAtk;
                    bool hasCard = P2HasUsableCard(p2, out hasAtk);
                    int curEnergy = p2.PlayerCombatState != null ? p2.PlayerCombatState.Energy : 0;
                    if (hasCard && curEnergy > 0)
                    {
                        GD.Print("[AiTeammate][Coord] p2-potion-continuation-aborted: running greedy fallback turn=" + TurnNumber);
                        TryFallbackGreedy(p2);
                    }
                    else
                    {
                        GD.Print("[AiTeammate][Coord] p2-potion-continuation-aborted: no playable cards, ending P2 turn");
                        EnqueueP2EndTurn(p2);
                    }
                    return;
                }

                if (P2PotionOpInFlightCount > 0 || IsPlayer2ActionInFlight())
                {
                    if ((now - _lastPotionDeferredLogTime).TotalSeconds >= 1.0)
                    {
                        _lastPotionDeferredLogTime = now;
                        GD.Print(string.Format("[AiTeammate][Coord] p2-potion-continuation-retry attempt={0}", PotionContinuationRetryCount));
                    }
                    PotionContinuationScheduled = false;
                    return;
                }

                int queueCount = GetP2QueuePlayCardCount(p2.NetId);
                if (queueCount > 0)
                {
                    if ((now - _lastPotionDeferredLogTime).TotalSeconds >= 1.0)
                    {
                        _lastPotionDeferredLogTime = now;
                        GD.Print(string.Format("[AiTeammate][Coord] p2-potion-continuation-retry attempt={0}", PotionContinuationRetryCount));
                    }
                    PotionContinuationScheduled = false;
                    return;
                }

                // Directive #5.48 Priority 4: Re-read actual P2 hand and current costs, don't deduce no-cards from energy<=0
                bool hasAttack;
                bool hasUsableCard = false;
                var hand = PileType.Hand.GetPile(p2);
                if (hand != null && hand.Cards != null)
                {
                    foreach (var card in hand.Cards)
                    {
                        if (card != null && CheckIsPlayable(card) && IsAffordable(card, p2))
                        {
                            hasUsableCard = true;
                            if (IsAttack(card)) hasAttack = true;
                            break;
                        }
                    }
                }

                if (!hasUsableCard)
                {
                    PendingPotionContinuation = false;
                    PotionContinuationScheduled = false;
                    GD.Print("[AiTeammate][Coord] p2-potion-continuation: no playable cards remaining, ending P2 turn");
                    EnqueueP2EndTurn(p2);
                    return;
                }

                GD.Print("[AiTeammate][Coord] p2-continuation-requested owner=P2 reason=potion-complete");

                // Clean stale deployment session without affecting active actions
                CleanHangingDeployment();
                IsDeploying = false;
                MidDeployStartTime = DateTime.MinValue;

                // Re-arm independent lifeline
                ArmIndependentP2Lifeline("potion-continuation");

                // Trigger single recalculation for P2
                PendingPotionContinuation = false;
                PotionContinuationScheduled = false;
                KickSolverRecalculation(state, "potion-complete");
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] ExecuteP2PotionContinuation exception: " + ex);
                PendingPotionContinuation = false;
                PotionContinuationScheduled = false;
            }
        }

        public static void ClearStaleSolverState(string reason)
        {
            try
            {
                IsDeploying = false;
                MidDeployStartTime = DateTime.MinValue;
                CleanHangingDeployment();
                GD.Print(string.Format("[AiTeammate][Coord] p2-stale-solver-cleared turn={0} reason={1}", TurnNumber, reason ?? "unknown"));
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] ClearStaleSolverState exception: " + ex);
            }
        }

        // ============================================================================================
        // Directive #5.91 T1 — CombatSolver per-turn-layer time budget de-truncation.
        //
        // CombatSolver divides `searchTimeLimitSeconds` evenly across its 8 turn layers, so 2s gave the
        // CURRENT turn layer only 250ms. On `completed_turns=0, play_depth=0` the search performs four
        // synchronous HEAP_RECLAIM GCs (270-364ms of wall clock), which blew that 250ms and truncated the
        // live turn at `play_depth=1 expanded=1` — the "1 card per turn" (and 0-card) boss turns in the
        // #5.90 run. Raising the limit to 8s widens the per-layer safety margin to 1000ms; the real stop
        // boundary stays `boundary=NodeLimit` (searchMaxExpandedNodes=4000, ~0.9-1.4s), so playback speed
        // is unchanged. `useEarlyTurnExploration` additionally makes the current layer expand first.
        // ============================================================================================
        public const int OptimalSolverTimeLimitSeconds = 4;
        public const int OptimalSolverMaxExpandedNodes = 2500;
        public const bool OptimalSolverEarlyTurnExploration = false;
        private static DateTime _lastSolverSettingsDiskSync = DateTime.MinValue;
        private static bool _solverSettingsEnforcedLogged = false;

        public static void EnsureOptimalCombatSolverSettings()
        {
            EnsureOptimalCombatSolverSettings(false);
        }

        public static void EnsureOptimalCombatSolverSettings(bool forceDiskSync)
        {
            bool runtimeFixed = false;
            bool diskFixed = false;
            string tlDeclared = "unknown";
            string nodesDeclared = "unknown";
            string etDeclared = "unknown";

            // 1) Runtime: mirror the values into CombatSolver.SolverSettings.Current so a search that
            //    starts before the next Load() already sees them. Pure in-memory property writes - this
            //    needs no CombatSolver API beyond reflection and cannot invalidate the assembly hash.
            try
            {
                Assembly csAsm = FindCombatSolverAssembly();
                if (csAsm != null)
                {
                    Type settingsType = csAsm.GetType("CombatSolver.SolverSettings");
                    Type dataType = csAsm.GetType("CombatSolver.SolverSettingsData");
                    if (settingsType != null && dataType != null)
                    {
                        PropertyInfo curProp = settingsType.GetProperty("Current", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static);
                        object data = curProp != null ? curProp.GetValue(null, null) : null;
                        if (data != null)
                        {
                            // Directive #5.92 T1: SearchTimeLimitSeconds is declared
                            // System.Nullable<System.Double>, NOT Nullable<int> (the #5.91 probe
                            // conclusion was wrong). The old `raw is int` test was therefore always
                            // false, `cur` stayed -1, and SetValue(int) threw
                            // "Object of type 'System.Int32' cannot be converted to type
                            // 'System.Nullable`1[System.Double]'" on EVERY combat (45 occurrences in
                            // one session). Convert to the property's real underlying type first.
                            PropertyInfo tlProp = dataType.GetProperty("SearchTimeLimitSeconds", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                            if (tlProp != null)
                            {
                                tlDeclared = DescribeSolverPropType(tlProp);
                                double cur;
                                bool hasCur = TryReadSolverNumericSetting(tlProp, data, out cur);
                                if (!hasCur || cur < 3.5 || cur > 4.5)
                                {
                                    if (WriteSolverNumericSetting(tlProp, data, OptimalSolverTimeLimitSeconds))
                                    {
                                        runtimeFixed = true;
                                        GD.Print(string.Format("[AiTeammate] [Diag] solver-settings-runtime-fix field=SearchTimeLimitSeconds declared={0} from={1} to={2}",
                                            tlDeclared, hasCur ? cur.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) : "null", OptimalSolverTimeLimitSeconds));
                                    }
                                }
                            }
                            PropertyInfo etProp = dataType.GetProperty("UseEarlyTurnExploration", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                            if (etProp != null)
                            {
                                etDeclared = DescribeSolverPropType(etProp);
                                object raw = etProp.GetValue(data, null);
                                bool cur = raw is bool && (bool)raw;
                                if (cur != OptimalSolverEarlyTurnExploration)
                                {
                                    etProp.SetValue(data, OptimalSolverEarlyTurnExploration, null);
                                    runtimeFixed = true;
                                    GD.Print(string.Format("[AiTeammate] [Diag] solver-settings-runtime-fix field=UseEarlyTurnExploration from={0} to={1}", cur, OptimalSolverEarlyTurnExploration));
                                }
                            }
                            PropertyInfo nodesProp = dataType.GetProperty("SearchMaxExpandedNodes", BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
                            if (nodesProp != null)
                            {
                                nodesDeclared = DescribeSolverPropType(nodesProp);
                                double curNodes;
                                bool hasNodes = TryReadSolverNumericSetting(nodesProp, data, out curNodes);
                                if (!hasNodes || curNodes > 2500 || curNodes < 1500)
                                {
                                    if (WriteSolverNumericSetting(nodesProp, data, OptimalSolverMaxExpandedNodes))
                                    {
                                        runtimeFixed = true;
                                        GD.Print(string.Format("[AiTeammate] [Diag] solver-settings-runtime-fix field=SearchMaxExpandedNodes declared={0} from={1} to={2}",
                                            nodesDeclared, hasNodes ? curNodes.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) : "null", OptimalSolverMaxExpandedNodes));
                                    }
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception exRt)
            {
                GD.PrintErr("[AiTeammate] [Diag] solver-settings-runtime-fix failed: " + exRt.Message);
            }

            // 2) Disk: keep %APPDATA%\SlayTheSpire2\combat_solver_settings.json in sync so the next load
            //    (and the next game session) starts from the same values. Throttled to one read per 30s
            //    unless forced, so calling this before every search stays cheap.
            try
            {
                if (forceDiskSync || _lastSolverSettingsDiskSync == DateTime.MinValue ||
                    (DateTime.UtcNow - _lastSolverSettingsDiskSync).TotalSeconds >= 30.0)
                {
                    _lastSolverSettingsDiskSync = DateTime.UtcNow;
                    diskFixed = SyncCombatSolverSettingsFile();
                }
            }
            catch (Exception exDisk)
            {
                GD.PrintErr("[AiTeammate] [Diag] solver-settings-disk-sync failed: " + exDisk.Message);
            }

            if (!_solverSettingsEnforcedLogged)
            {
                _solverSettingsEnforcedLogged = true;
                GD.Print("[AiTeammate] [Diag] solver-settings-enforced timeLimitSec=4 maxNodes=2500 earlyTurnExploration=False");
                GD.Print("[AiTeammate] [Diag] solver-settings-declared-types timeLimitSeconds=" + tlDeclared + " maxExpandedNodes=" + nodesDeclared + " earlyTurnExploration=" + etDeclared);
            }
            if (runtimeFixed || diskFixed)
            {
                GD.Print(string.Format("[AiTeammate] [Diag] solver-settings-applied runtimeFixed={0} diskFixed={1}", runtimeFixed, diskFixed));
            }
        }

        // Directive #5.92 T1: CombatSolver declares SearchTimeLimitSeconds / SearchMaxExpandedNodes as
        // Nullable<T>. Writing a plain boxed int/double to a Nullable<T> property throws
        // ArgumentException ("Object of type 'X' cannot be converted to type 'Nullable`1[Y]'"), which is
        // exactly the 45-per-session failure the #5.91 build produced. Every numeric write is converted
        // to the property's real underlying type first; every read tolerates null.
        private static Type SolverSettingUnderlyingType(PropertyInfo prop)
        {
            if (prop == null) return null;
            try { return Nullable.GetUnderlyingType(prop.PropertyType) ?? prop.PropertyType; }
            catch { return null; }
        }

        private static string DescribeSolverPropType(PropertyInfo prop)
        {
            try
            {
                if (prop == null) return "missing";
                Type u = Nullable.GetUnderlyingType(prop.PropertyType);
                return u != null ? "Nullable<" + u.Name + ">" : prop.PropertyType.Name;
            }
            catch { return "unknown"; }
        }

        private static bool TryReadSolverNumericSetting(PropertyInfo prop, object target, out double value)
        {
            value = 0.0;
            try
            {
                if (prop == null || target == null) return false;
                object raw = prop.GetValue(target, null);
                if (raw == null) return false;
                value = Convert.ToDouble(raw, System.Globalization.CultureInfo.InvariantCulture);
                return true;
            }
            catch { return false; }
        }

        private static bool WriteSolverNumericSetting(PropertyInfo prop, object target, double value)
        {
            try
            {
                if (prop == null || target == null) return false;
                Type underlying = SolverSettingUnderlyingType(prop);
                if (underlying == null) return false;
                object boxed = Convert.ChangeType(value, underlying, System.Globalization.CultureInfo.InvariantCulture);
                prop.SetValue(target, boxed, null);
                return true;
            }
            catch (Exception ex)
            {
                // Deliberately NOT tagged "solver-settings-runtime-fix failed": the verification greps
                // that exact phrase and it must only ever come from the outer guard.
                GD.PrintErr("[AiTeammate] [Diag] solver-settings-numeric-write-failed field=" + (prop != null ? prop.Name : "?") + " reason=" + ex.Message);
                return false;
            }
        }

        public static Assembly FindCombatSolverAssembly()
        {
            try
            {
                Assembly[] asms = AppDomain.CurrentDomain.GetAssemblies();
                for (int i = 0; i < asms.Length; i++)
                {
                    Assembly a = asms[i];
                    if (a == null) continue;
                    string n = a.GetName().Name;
                    if (n == "CombatSolver") return a;
                }
            }
            catch { }
            return null;
        }

        public static Assembly FindDualRoleAdventureAssembly()
        {
            try
            {
                Assembly[] asms = AppDomain.CurrentDomain.GetAssemblies();
                for (int i = 0; i < asms.Length; i++)
                {
                    Assembly a = asms[i];
                    if (a == null) continue;
                    string n = a.GetName().Name;
                    if (n == "DualRoleAdventure") return a;
                }
            }
            catch { }
            return null;
        }

        private static string GetCombatSolverSettingsPath()
        {
            try
            {
                string appData = null;
                try { appData = System.Environment.GetFolderPath(System.Environment.SpecialFolder.ApplicationData); }
                catch { }
                string primary = !string.IsNullOrEmpty(appData)
                    ? System.IO.Path.Combine(appData, "SlayTheSpire2", "combat_solver_settings.json")
                    : null;
                if (primary != null && System.IO.File.Exists(primary)) return primary;
                string userDir = null;
                try { userDir = OS.GetUserDataDir(); }
                catch { }
                if (!string.IsNullOrEmpty(userDir))
                {
                    string alt = System.IO.Path.Combine(userDir, "combat_solver_settings.json");
                    if (System.IO.File.Exists(alt)) return alt;
                }
                return primary;
            }
            catch { return null; }
        }

        // Text-level patch: preserves every other key, the key order and the file formatting. A full
        // JSON round-trip would re-serialize CombatSolver's own DTO and could drop unknown fields.
        private static string PatchCombatSolverSettingsJson(string json)
        {
            if (string.IsNullOrEmpty(json)) return json;
            string result = json;
            try
            {
                System.Text.RegularExpressions.Regex numRe = new System.Text.RegularExpressions.Regex(
                    "\"searchTimeLimitSeconds\"(\\s*:\\s*)(-?[0-9]+(?:\\.[0-9]+)?|null)");
                System.Text.RegularExpressions.Match m = numRe.Match(result);
                if (m.Success)
                {
                    string raw = m.Groups[2].Value;
                    double parsed = 0.0;
                    bool ok = !string.Equals(raw, "null", StringComparison.OrdinalIgnoreCase) &&
                              double.TryParse(raw, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out parsed);
                    if (!ok || parsed < 3.5 || parsed > 4.5)
                    {
                        result = numRe.Replace(result, "\"searchTimeLimitSeconds\"" + m.Groups[1].Value + OptimalSolverTimeLimitSeconds.ToString(System.Globalization.CultureInfo.InvariantCulture), 1);
                    }
                }
                System.Text.RegularExpressions.Regex boolRe = new System.Text.RegularExpressions.Regex(
                    "\"useEarlyTurnExploration\"(\\s*:\\s*)(true|false)");
                System.Text.RegularExpressions.Match bm = boolRe.Match(result);
                if (bm.Success && string.Equals(bm.Groups[2].Value, "true", StringComparison.OrdinalIgnoreCase))
                {
                    result = boolRe.Replace(result, "\"useEarlyTurnExploration\"" + bm.Groups[1].Value + "false", 1);
                }
                System.Text.RegularExpressions.Regex nodesRe = new System.Text.RegularExpressions.Regex(
                    "\"searchMaxExpandedNodes\"(\\s*:\\s*)(-?[0-9]+|null)");
                System.Text.RegularExpressions.Match nm = nodesRe.Match(result);
                if (nm.Success)
                {
                    string raw = nm.Groups[2].Value;
                    int parsed = 0;
                    bool ok = !string.Equals(raw, "null", StringComparison.OrdinalIgnoreCase) &&
                              int.TryParse(raw, out parsed);
                    if (!ok || parsed > 2500 || parsed < 1500)
                    {
                        result = nodesRe.Replace(result, "\"searchMaxExpandedNodes\"" + nm.Groups[1].Value + OptimalSolverMaxExpandedNodes.ToString(System.Globalization.CultureInfo.InvariantCulture), 1);
                    }
                }
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate] [Diag] solver-settings-json-patch failed: " + ex.Message);
                return json;
            }
            return result;
        }

        private static bool SyncCombatSolverSettingsFile()
        {
            string path = GetCombatSolverSettingsPath();
            if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path)) return false;
            string json = System.IO.File.ReadAllText(path);
            string patched = PatchCombatSolverSettingsJson(json);
            if (patched == null || string.Equals(patched, json, StringComparison.Ordinal)) return false;
            string tmp = path + ".aiteammate.tmp";
            System.IO.File.WriteAllText(tmp, patched);
            try { System.IO.File.Copy(path, path + ".aiteammate.bak", true); }
            catch { }
            System.IO.File.Copy(tmp, path, true);
            try { System.IO.File.Delete(tmp); }
            catch { }
            GD.Print(string.Format("[AiTeammate] [Diag] solver-settings-disk-fix path={0} timeLimitSec={1} maxNodes={2} earlyTurnExploration={3}", path, OptimalSolverTimeLimitSeconds, OptimalSolverMaxExpandedNodes, OptimalSolverEarlyTurnExploration));
            return true;
        }

        // ============================================================================================
        // Directive #5.92 T3 - CombatSolver battle log archiver.
        //
        // CombatSolver keeps only the most recent combat-*.jsonl per session, so the next battle
        // destroys the evidence needed to attribute the previous one (the 23:25 session played 4
        // battles and only the last jsonl survived). This copies them out ONE WAY into
        // %APPDATA%\SlayTheSpire2\logs\CombatSolverArchive\ and trims the archive to the newest 10.
        // Source files are opened read-only and never modified, moved or deleted.
        // ============================================================================================
        public const int SolverLogArchiveKeepCount = 10;
        private static readonly HashSet<string> _solverLogArchivedNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        // Directive #5.92 T3: edge detector + bounded retry. CombatSolver may still hold the jsonl open
        // for a few hundred ms after the last enemy dies, so the falling edge arms a short retry window
        // (6 x 250ms timer ticks). ArchiveCombatSolverLogs dedups by file name, so repeated attempts are
        // free once the file has been copied.
        private static bool _wasInCombatForLogArchive = false;
        private static int _combatLogArchivePendingTicks = 0;

        // Called from the SetUpCombat prefix so the edge detector starts each battle already "inside"
        // combat (otherwise the first tick after a battle start could look like a falling edge).
        public static void NotifyCombatStartForLogArchive()
        {
            _wasInCombatForLogArchive = true;
            _combatLogArchivePendingTicks = 0;
        }

        public static void CheckCombatEndedForLogArchive()
        {
            bool nowInCombat = IsInCombat();
            if (_wasInCombatForLogArchive && !nowInCombat) _combatLogArchivePendingTicks = 6;
            _wasInCombatForLogArchive = nowInCombat;
            if (_combatLogArchivePendingTicks > 0)
            {
                _combatLogArchivePendingTicks--;
                ArchiveCombatSolverLogs();
            }
        }

        public static void ArchiveCombatSolverLogs()
        {
            try
            {
                string appData = null;
                try { appData = System.Environment.GetFolderPath(System.Environment.SpecialFolder.ApplicationData); }
                catch { }
                if (string.IsNullOrEmpty(appData)) return;
                string root = System.IO.Path.Combine(appData, "SlayTheSpire2", "logs", "CombatSolver");
                if (!System.IO.Directory.Exists(root)) return;
                string archive = System.IO.Path.Combine(appData, "SlayTheSpire2", "logs", "CombatSolverArchive");

                List<string> copied = new List<string>();
                // Only the CURRENT session directory (<pid>-<hash>), picked as the most recently written
                // one: process.jsonl in it is appended to continuously while the game runs. The root also
                // holds every PREVIOUS session's directory, and copying all of them would dump dozens of
                // unrelated battles into the archive on the first call and immediately trim most away.
                string sessionDir = null;
                try
                {
                    string[] dirs = System.IO.Directory.GetDirectories(root);
                    DateTime newest = DateTime.MinValue;
                    for (int i = 0; i < dirs.Length; i++)
                    {
                        // Directory mtime does NOT change when a contained file is appended to, so the
                        // "most recent session" decision has to look at the files themselves.
                        DateTime stamp = System.IO.Directory.GetLastWriteTimeUtc(dirs[i]);
                        try
                        {
                            string[] probe = System.IO.Directory.GetFiles(dirs[i], "*.jsonl");
                            for (int j = 0; j < probe.Length; j++)
                            {
                                DateTime ft = System.IO.File.GetLastWriteTimeUtc(probe[j]);
                                if (ft > stamp) stamp = ft;
                            }
                        }
                        catch { }
                        if (stamp > newest) { newest = stamp; sessionDir = dirs[i]; }
                    }
                }
                catch { }
                if (string.IsNullOrEmpty(sessionDir)) return;
                string[] files = System.IO.Directory.GetFiles(sessionDir, "combat-*.jsonl");
                for (int f = 0; f < files.Length; f++)
                {
                    try
                    {
                        string name = System.IO.Path.GetFileName(files[f]);
                        string dest = System.IO.Path.Combine(archive, name);
                        // One copy per battle: the file for the CURRENT battle is created after this
                        // hook runs, so whatever is on disk here is a completed battle.
                        if (_solverLogArchivedNames.Contains(name) && System.IO.File.Exists(dest)) continue;
                        System.IO.Directory.CreateDirectory(archive);
                        System.IO.File.Copy(files[f], dest, true);
                        System.IO.FileInfo fi = new System.IO.FileInfo(dest);
                        _solverLogArchivedNames.Add(name);
                        copied.Add(name + "|" + fi.Length.ToString(System.Globalization.CultureInfo.InvariantCulture));
                    }
                    catch (Exception exOne)
                    {
                        GD.PrintErr("[AiTeammate] [Diag] solver-log-archive-skip file=" + System.IO.Path.GetFileName(files[f]) + " reason=" + exOne.Message);
                    }
                }

                string[] archived = System.IO.Directory.Exists(archive)
                    ? System.IO.Directory.GetFiles(archive, "combat-*.jsonl")
                    : new string[0];
                if (archived.Length > SolverLogArchiveKeepCount)
                {
                    // File.Copy preserves LastWriteTime, so this orders by ORIGINAL battle time.
                    Array.Sort(archived, delegate (string a, string b)
                    {
                        return System.IO.File.GetLastWriteTimeUtc(a).CompareTo(System.IO.File.GetLastWriteTimeUtc(b));
                    });
                    int toDelete = archived.Length - SolverLogArchiveKeepCount;
                    for (int i = 0; i < toDelete; i++)
                    {
                        try { System.IO.File.Delete(archived[i]); }
                        catch (Exception exDel) { GD.PrintErr("[AiTeammate] [Diag] solver-log-archive-trim-failed file=" + System.IO.Path.GetFileName(archived[i]) + " reason=" + exDel.Message); }
                    }
                    archived = System.IO.Directory.GetFiles(archive, "combat-*.jsonl");
                }

                int kept = archived.Length;
                for (int i = 0; i < copied.Count; i++)
                {
                    string[] parts = copied[i].Split('|');
                    GD.Print(string.Format("[AiTeammate] [Diag] solver-log-archived file={0} size={1} kept={2}", parts[0], parts[1], kept));
                }
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate] [Diag] solver-log-archive-failed reason=" + ex.Message);
            }
        }

        public static bool IsSolverGenuinelyActive(Player p2, int queueCount, bool inflight, out string staleReason)
        {
            staleReason = null;
            DateTime now = DateTime.UtcNow;

            if (inflight) return true;
            if (queueCount > 0) return true;

            if (PlanEmptyRecoveryInProgress && (now - PlanEmptyRecoveryStartTime).TotalSeconds < 3.0)
            {
                return true;
            }

            bool isSearching = IsSolverSearching();
            bool isDeploying = IsSolverDeploying() || IsDeploying;

            if (!isSearching && !isDeploying)
            {
                return false;
            }

            // Check if solver is stale:
            // A. Deployment already completed this turn, queue is empty, no action in flight
            // Directive #5.90 T1.3: never declare an ACTIVELY SEARCHING solver stale just because an
            // earlier deployment completed in the same turn. ResetTurnState("OnEndedTurnLocally") (P1
            // pressing End Turn) sets HasCompletedDeploymentThisTurn=true mid-round, which used to kill
            // P2's live search with staleReason=deployment-already-completed and fire greedy while
            // solverActive=True.
            if (HasCompletedDeploymentThisTurn && !isSearching && queueCount == 0 && !inflight)
            {
                staleReason = "deployment-already-completed";
                return false;
            }

            // B. Plan-empty confirmed, queue is empty, no action in flight
            if (SolverEarlyEndReportedThisTurn && queueCount == 0 && !inflight)
            {
                staleReason = "plan-empty-confirmed";
                return false;
            }

            // C. Search heartbeat missed (> 5s) or search duration exceeded (> 8s)
            if (isSearching)
            {
                if (LastSearchHeartbeatTime != DateTime.MinValue && (now - LastSearchHeartbeatTime).TotalSeconds >= 5.0)
                {
                    staleReason = "search-heartbeat-missed";
                    return false;
                }
                if (SearchAliveStartTime != DateTime.MinValue && (now - SearchAliveStartTime).TotalSeconds >= 8.0)
                {
                    staleReason = "search-duration-exceeded";
                    return false;
                }
            }

            // D. Deployment hung with no actions in flight and empty queue
            if (isDeploying)
            {
                if (DeployStartTime != DateTime.MinValue && (now - DeployStartTime).TotalSeconds >= 2.0 && queueCount == 0 && !inflight)
                {
                    staleReason = "deploy-no-actions-timeout";
                    return false;
                }
            }

            return true;
        }

        private static string _lastFallbackDeferLogKey = null;

        public static bool TriggerP2Fallback(Player p2, CombatState state)
        {
            return TriggerP2Fallback(p2, state, "unspecified");
        }

        // Directive #5.91 T3.2: returns TRUE only when greedy actually enqueued card actions.
        public static bool TriggerP2Fallback(Player p2, CombatState state, string trigger)
        {
            if (p2 == null || P2FallbackExecutedThisTurn || P2FallbackExhaustedThisTurn) return false;

            // #5.91 T3.2: never latch P2FallbackExecutedThisTurn while CombatSolver still owns the turn.
            // The #5.90 watchdog called this at 1.2s while the recalc was still searching;
            // TryFallbackGreedy then refused (solver-active) but the "executed" latch was already set,
            // so CheckP2EndTurnGate later allowed EndTurn with reason=recovery-exhausted without a
            // single greedy card ever being played (RC-3). Latch only the "requested" flag and let a
            // later watchdog/gate pass do the real attempt.
            if (IsSolverSearching() || IsSolverDeploying() || IsDeploying)
            {
                PlanEmptyFallbackRequestedThisTurn = true;
                string key = (trigger ?? "unspecified") + "|" + TurnNumber;
                if (!string.Equals(_lastFallbackDeferLogKey, key, StringComparison.Ordinal))
                {
                    _lastFallbackDeferLogKey = key;
                    GD.Print(string.Format("[AiTeammate][Coord] p2-fallback-deferred reason=solver-active trigger={0} searching={1} deploying={2} turn={3}",
                        trigger ?? "unspecified", IsSolverSearching(), IsSolverDeploying() || IsDeploying, TurnNumber));
                }
                return false;
            }

            P2FallbackExecutedThisTurn = true;
            PlanEmptyFallbackRequestedThisTurn = true;

            int energy = p2.PlayerCombatState != null ? p2.PlayerCombatState.Energy : 0;
            int hand = GetPlayerHandCardCount(p2);

            GD.Print(string.Format("[AiTeammate][Coord] p2-fallback-start turn={0} hand={1} energy={2} trigger={3}", TurnNumber, hand, energy, trigger ?? "unspecified"));

            bool enqueued = TryFallbackGreedy(p2);
            if (!enqueued && (IsSolverSearching() || IsSolverDeploying() || IsDeploying))
            {
                // Directive #5.90 T1.3: greedy refused because CombatSolver still owns the turn. Do not
                // latch "exhausted" and do not force an end turn - hand the turn back to the solver.
                P2FallbackExecutedThisTurn = false;
                GD.Print(string.Format("[AiTeammate][Coord] p2-fallback-deferred reason=solver-active turn={0}", TurnNumber));
                return false;
            }
            if (!enqueued)
            {
                GD.Print(string.Format("[AiTeammate][Coord] p2-fallback-exhausted turn={0}", TurnNumber));
                P2FallbackExhaustedThisTurn = true;
                LogFallbackExhaustedSet("p2-fallback-exhausted");
                PlanEmptyRecoveryInProgress = false;
                EnqueueP2EndTurn(p2);
                return false;
            }
            return true;
        }

        // Directive #5.92 T2.2: one-shot continuation attempt driven from CompleteDeploymentPostfix -
        // the only moment where (a) the solver's own EndTurn has already been suppressed by the gate and
        // (b) deployment is genuinely over, so TryFallbackGreedy's solver-active guard can pass.
        // Contract: every exit either plays cards or explicitly re-arms EndTurn, so a deferred EndTurn can
        // never turn into a stalled P2 turn. The flag is burned BEFORE any work so it cannot re-enter.
        public static void TryRunPostDeployContinuation()
        {
            if (!P2PendingPostDeployContinuation) return;
            P2PendingPostDeployContinuation = false;
            DateTime since = P2PendingPostDeployContinuationSince;
            P2PendingPostDeployContinuationSince = DateTime.MinValue;
            P2PendingPostDeployContinuationTurn = -1;
            double waited = since != DateTime.MinValue ? (DateTime.UtcNow - since).TotalSeconds : 0.0;
            string stage = "entry";
            try
            {
                CombatState cs = CombatManager.Instance != null ? CombatManager.Instance.DebugOnlyGetState() : null;
                Player p2 = (cs != null && cs.Players != null && cs.Players.Count > 1) ? cs.Players[cs.Players.Count - 1] : null;
                if (p2 == null || cs == null || !IsInCombat() || !IsPlayPhase())
                {
                    GD.Print("[AiTeammate][Coord] p2-postdeploy-continuation skipped reason=conditions-changed detail=not-in-play-phase turn=" + TurnNumber);
                    return;
                }
                if (P2FallbackExecutedThisTurn || P2FallbackExhaustedThisTurn)
                {
                    GD.Print("[AiTeammate][Coord] p2-postdeploy-continuation skipped reason=conditions-changed detail=fallback-already-used turn=" + TurnNumber);
                    return;
                }
                if (!P2SuspectTruncatedAfterOneCardThisTurn && P2PlayedCardsThisTurn > P2PlayedCardsAtRecalcStart)
                {
                    GD.Print("[AiTeammate][Coord] p2-postdeploy-continuation skipped reason=conditions-changed detail=cards-already-played turn=" + TurnNumber);
                    return;
                }
                if (HasSolverSatisfiedTurnPlan(p2, cs))
                {
                    GD.Print("[AiTeammate][Coord] p2-postdeploy-continuation skipped reason=conditions-changed detail=plan-satisfied turn=" + TurnNumber);
                    EnqueueP2EndTurn(p2);
                    return;
                }
                stage = "solver-busy-check";
                if (IsSolverSearching() || IsSolverDeploying() || IsDeploying)
                {
                    // A fresh search took over. Hand the turn back explicitly - the gate swallowed the
                    // solver's original EndTurn, so nothing else would end this turn.
                    GD.Print(string.Format("[AiTeammate][Coord] p2-postdeploy-continuation skipped reason=conditions-changed detail=solver-busy searching={0} deploying={1} turn={2}",
                        IsSolverSearching(), IsSolverDeploying() || IsDeploying, TurnNumber));
                    EnqueueP2EndTurn(p2);
                    return;
                }
                stage = "playability-check";
                bool hasAtk;
                if (!P2HasMeaningfulPlayable(p2, out hasAtk))
                {
                    GD.Print("[AiTeammate][Coord] p2-postdeploy-continuation skipped reason=no-playables turn=" + TurnNumber);
                    EnqueueP2EndTurn(p2);
                    return;
                }
                stage = "greedy";
                int hand = GetPlayerHandCardCount(p2);
                int energy = p2.PlayerCombatState != null ? p2.PlayerCombatState.Energy : 0;
                bool played = TriggerP2Fallback(p2, cs, "postdeploy-continuation");
                if (played)
                {
                    GD.Print(string.Format("[AiTeammate][Coord] p2-postdeploy-continuation played=True enqueued={0} hand={1} energy={2} waited={3:F2}s turn={4}",
                        GetP2QueuePlayCardCount(p2.NetId), hand, energy, waited, TurnNumber));
                }
                else
                {
                    // TriggerP2Fallback's exhausted branch already enqueued the EndTurn for us.
                    GD.Print(string.Format("[AiTeammate][Coord] p2-postdeploy-continuation skipped reason=no-playables detail=greedy-declined hand={0} energy={1} waited={2:F2}s turn={3}",
                        hand, energy, waited, TurnNumber));
                }
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] p2-postdeploy-continuation-failed reason=" + ex.Message + " stage=" + stage + " turn=" + TurnNumber);
                // Fail-open: never leave a swallowed EndTurn behind.
                try
                {
                    Player p2f = FlowCoordinator.GetPlayer2();
                    if (p2f != null) EnqueueP2EndTurn(p2f);
                }
                catch { }
            }
        }

        // Directive #5.92 T2.1: gate-side half of the post-deploy continuation.
        // Returns 0 = not applicable (gate continues normally), 1 = DEFER (gate returns false),
        //         2 = ALLOW (gate returns true, safety valve fired).
        // Business conditions mirror #5.91 T3.3 exactly; the only difference is that the solver is still
        // deploying, which is precisely why T3.3's idle guard could never match this timing.
        private static int TryHandleRecalcEmptyDeployingContinuation(Player p2, string caller, int queueCount, bool inflight, int hand, int energy, bool solverPlanSatisfied, bool genuinelyActive)
        {
            try
            {
                bool isRecalcEmpty = PlanEmptyRecoveryAttemptedThisTurn && (P2PlayedCardsThisTurn <= P2PlayedCardsAtRecalcStart);
                bool isSuspectTruncated = P2SuspectTruncatedAfterOneCardThisTurn && (P2PlayedCardsThisTurn >= 1);
                if (!isRecalcEmpty && !isSuspectTruncated) return 0;
                if (P2FallbackExecutedThisTurn || P2FallbackExhaustedThisTurn) return 0;
                if (solverPlanSatisfied || genuinelyActive || queueCount > 0 || inflight) return 0;
                if (!(IsSolverDeploying() || IsDeploying)) return 0;
                bool hasAttackIgnored;
                if (!P2HasMeaningfulPlayable(p2, out hasAttackIgnored)) return 0;

                bool sameTurnPending = P2PendingPostDeployContinuation && P2PendingPostDeployContinuationTurn == TurnNumber;
                double waitedSec = (sameTurnPending && P2PendingPostDeployContinuationSince != DateTime.MinValue)
                    ? (DateTime.UtcNow - P2PendingPostDeployContinuationSince).TotalSeconds : 0.0;

                // Hard safety valve: never hold the EndTurn for more than 5s. Deployment stalls and the
                // 12s watchdog are both worse than one empty turn, so this always fails open.
                if (sameTurnPending && waitedSec >= P2PostDeployContinuationTimeoutSeconds)
                {
                    P2PendingPostDeployContinuation = false;
                    P2PendingPostDeployContinuationSince = DateTime.MinValue;
                    P2PendingPostDeployContinuationTurn = -1;
                    GD.Print(string.Format("[AiTeammate][Coord] p2-endturn-gate decision=allow reason=deploying-continuation-timeout caller={0} hand={1} energy={2} queue={3} inflight={4} waited={5:F1}s turn={6}",
                        caller ?? "unknown", hand, energy, queueCount, inflight, waitedSec, TurnNumber));
                    return 2;
                }
                if (!sameTurnPending)
                {
                    P2PendingPostDeployContinuation = true;
                    P2PendingPostDeployContinuationSince = DateTime.UtcNow;
                    P2PendingPostDeployContinuationTurn = TurnNumber;
                }
                GD.Print(string.Format("[AiTeammate][Coord] p2-endturn-gate decision=defer reason=deploying-recalc-empty-continuation caller={0} hand={1} energy={2} played={3} played-at-recalc={4} queue={5} inflight={6} waited={7:F1}s turn={8}",
                    caller ?? "unknown", hand, energy, P2PlayedCardsThisTurn, P2PlayedCardsAtRecalcStart, queueCount, inflight, waitedSec, TurnNumber));
                return 1;
            }
            catch (Exception ex)
            {
                // Fail-open: a brand-new code path must never be the reason a P2 turn locks up.
                GD.PrintErr("[AiTeammate][Coord] p2-endturn-gate deploy-continuation check failed: " + ex.Message);
                return 0;
            }
        }

        public static void ExecutePlanEmptyRecovery(Player p2, CombatState state, string trigger)
        {
            try
            {
                if (p2 == null || !IsInCombat() || !IsPlayPhase()) return;
                if (P2FallbackExhaustedThisTurn) return;
                if (PlanEmptyRecoveryAttemptedThisTurn)
                {
                    // Directive #5.91 T3.1: while the recalc is still in flight the watchdog owns the
                    // timing (1.2s idle grace / 8.5s hard cap). Preempting here re-introduced the exact
                    // 1.2s race that latched P2FallbackExecutedThisTurn while TryFallbackGreedy refused.
                    if (!P2FallbackExecutedThisTurn && !PlanEmptyRecoveryInProgress
                        && !IsSolverSearching() && !IsSolverDeploying() && !IsDeploying)
                    {
                        TriggerP2Fallback(p2, state, "recovery-already-attempted");
                    }
                    return;
                }

                bool hasAtk;
                bool playable = P2HasUsableCard(p2, out hasAtk);
                int energy = p2.PlayerCombatState != null ? p2.PlayerCombatState.Energy : 0;
                int hand = GetPlayerHandCardCount(p2);

                if (!playable || energy <= 0)
                {
                    PlanEmptyRecoveryAttemptedThisTurn = true;
                    P2FallbackExhaustedThisTurn = true;
                    LogFallbackExhaustedSet("plan-empty-recovery-skipped");
                    PlanEmptyRecoveryInProgress = false;
                    GD.Print(string.Format("[AiTeammate][Coord] p2-plan-empty-recovery-skipped reason={0} turn={1}", 
                        !playable ? "no-playable-cards" : "no-energy", TurnNumber));
                    return;
                }

                ulong p2NetId = p2.NetId;
                int queueCount = GetP2QueuePlayCardCount(p2NetId);
                bool inflight = IsPlayer2ActionInFlight();
                if (queueCount > 0 || inflight) return;

                PlanEmptyRecoveryAttemptedThisTurn = true;
                PlanEmptyRecoveryInProgress = true;
                PlanEmptyRecoveryStartTime = DateTime.UtcNow;
                // Directive #5.91 T3.3: baseline for "the recalc produced no NEW card".
                P2PlayedCardsAtRecalcStart = P2PlayedCardsThisTurn;

                GD.Print(string.Format("[AiTeammate][Coord] p2-plan-empty-recovery-start turn={0} hand={1} energy={2}", TurnNumber, hand, energy));

                // 1. Clean current stale deployment/search session
                ClearStaleSolverState("plan-empty-recovery");

                // 2. Request new P2 RequestSearch once
                PlanEmptyRecalcRequestedThisTurn = true;
                GD.Print(string.Format("[AiTeammate][Coord] p2-plan-empty-recalc-requested turn={0}", TurnNumber));

                if (state == null)
                {
                    var cm = CombatManager.Instance;
                    if (cm != null) state = cm.DebugOnlyGetState();
                }

                lock (LifelineGate)
                {
                    IndependentLifelineStartTime = DateTime.UtcNow;
                    IndependentLifelineFired = false;
                }

                RequestRecalculation(state, "plan-empty-retry");
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] ExecutePlanEmptyRecovery exception: " + ex);
                PlanEmptyRecoveryInProgress = false;
            }
        }

        public static void CheckPlanEmptyRecoveryWatchdog(DateTime now)
        {
            try
            {
                if (!IsInCombat() || !IsPlayPhase()) return;

                // Directive #5.48 Priority 2: Pause P2 recovery while P1 is gathering player choice
                if (IsPlayer1InChoiceScreen())
                {
                    if (PlanEmptyRecoveryStartTime != DateTime.MinValue)
                    {
                        PlanEmptyRecoveryStartTime = DateTime.UtcNow; // Preserve budget
                    }
                    if (P2FallbackExhaustedThisTurn)
                    {
                        P2PendingEndTurnWakeup = true;
                        GD.Print("[AiTeammate][Coord] p2-force-end-blocked owner=P2 reason=p1-gathering-choice");
                    }
                    return;
                }

                Player p2 = FlowCoordinator.GetPlayer2();
                if (p2 == null || p2.PlayerCombatState == null) return;

                if (P2FallbackExhaustedThisTurn)
                {
                    var cm = CombatManager.Instance;
                    if (cm != null && !cm.IsPlayerReadyToEndTurn(p2))
                    {
                        EnqueueP2EndTurn(p2);
                    }
                    return;
                }

                int energy = p2.PlayerCombatState.Energy;
                if (energy <= 0)
                {
                    if (PlanEmptyRecoveryInProgress || PlanEmptyRecoveryAttemptedThisTurn)
                    {
                        P2FallbackExhaustedThisTurn = true;
                        LogFallbackExhaustedSet("plan-empty-exhausted-no-energy");
                        PlanEmptyRecoveryInProgress = false;
                        GD.Print(string.Format("[AiTeammate][Coord] p2-plan-empty-fallback-exhausted turn={0}", TurnNumber));
                        EnqueueP2EndTurn(p2);
                    }
                    return;
                }

                bool hasAtk;
                bool hasUsable = P2HasUsableCard(p2, out hasAtk);
                if (!hasUsable)
                {
                    if (PlanEmptyRecoveryInProgress || PlanEmptyRecoveryAttemptedThisTurn)
                    {
                        P2FallbackExhaustedThisTurn = true;
                        LogFallbackExhaustedSet("plan-empty-exhausted-no-usable");
                        PlanEmptyRecoveryInProgress = false;
                        GD.Print(string.Format("[AiTeammate][Coord] p2-plan-empty-fallback-exhausted turn={0}", TurnNumber));
                        EnqueueP2EndTurn(p2);
                    }
                    return;
                }

                ulong p2NetId = p2.NetId;
                int queueCount = GetP2QueuePlayCardCount(p2NetId);
                bool inflight = IsPlayer2ActionInFlight();
                if (queueCount > 0 || inflight) return;

                string staleReason;
                bool genuinelyActive = IsSolverGenuinelyActive(p2, queueCount, inflight, out staleReason);
                if (!genuinelyActive && staleReason != null)
                {
                    ClearStaleSolverState(staleReason);
                }

                if (PlanEmptyRecoveryInProgress)
                {
                    if (PlanEmptyRecalcRequestedThisTurn && !P2FallbackExecutedThisTurn)
                    {
                        double elapsed = (now - PlanEmptyRecoveryStartTime).TotalSeconds;
                        bool solverBusy = IsSolverSearching() || IsSolverDeploying() || IsDeploying;
                        if (solverBusy)
                        {
                            // Directive #5.91 T3.1: do NOT preempt an in-flight recalc. The old 1.2s
                            // timeout fired while CombatSolver was still searching; TryFallbackGreedy
                            // then refused (solver-active) while TriggerP2Fallback had already latched
                            // P2FallbackExecutedThisTurn=true, which later let the gate allow EndTurn with
                            // reason=recovery-exhausted without one greedy card being played. Wait for
                            // the search to finish, with 8.5s as an absolute safety cap.
                            if (elapsed >= PlanEmptyRecoveryHardCapSeconds)
                            {
                                GD.Print(string.Format("[AiTeammate][Coord] plan-empty-recovery-hard-cap elapsed={0:F2}s turn={1}", elapsed, TurnNumber));
                                var csHard = CombatManager.Instance != null ? CombatManager.Instance.DebugOnlyGetState() : null;
                                TriggerP2Fallback(p2, csHard, "recovery-hard-cap");
                            }
                        }
                        else if (elapsed >= 1.2)
                        {
                            // Solver finished and P2 still produced nothing: one real greedy attempt.
                            var csIdle = CombatManager.Instance != null ? CombatManager.Instance.DebugOnlyGetState() : null;
                            TriggerP2Fallback(p2, csIdle, "recovery-idle-timeout");
                        }
                    }
                    return;
                }

                if (!PlanEmptyRecoveryAttemptedThisTurn && HasCompletedDeploymentThisTurn && !genuinelyActive)
                {
                    var cm = CombatManager.Instance;
                    var cs = cm != null ? cm.DebugOnlyGetState() : null;
                    // Directive #5.90 T1: never start plan-empty recovery when the solver already
                    // satisfied its plan for this turn.
                    if (HasSolverSatisfiedTurnPlan(p2, cs))
                    {
                        GD.Print(string.Format("[AiTeammate][Coord] plan-empty-recovery-suppressed reason=plan-satisfied plan-len={0} planned={1} played={2} enqueued={3} turn={4}", P2PlanLengthThisTurn, P2PlannedCardActionsThisTurn, P2PlayedCardsThisTurn, P2EnqueuedCardActionsThisTurn, TurnNumber));
                    }
                    else
                    {
                        ExecutePlanEmptyRecovery(p2, cs, "tick-watchdog");
                    }
                }
                else if (IsPlayer1Dead() && !IsPlayer2Dead() && (PlanEmptyRecoveryAttemptedThisTurn || HasCompletedDeploymentThisTurn) && !genuinelyActive)
                {
                    CheckDeadP1ZeroProgressFallback("watchdog-dead-p1");
                }
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] CheckPlanEmptyRecoveryWatchdog exception: " + ex);
            }
        }

        public static bool CheckForceEndTurnGuard(CombatManager cm, CombatState state, Player player2, string triggerSource, out string blockReason)
        {
            blockReason = null;
            if (AreAllPlayersDead() || IsTerminalCombatFinalized)
            {
                blockReason = "all-players-dead";
                LogTerminalCombatFinalized("all-players-dead");
                return false;
            }
            try
            {
                if (player2 == null) return true;

                // 1. P2PotionOpInFlightCount > 0
                if (P2PotionOpInFlightCount > 0)
                {
                    blockReason = "potion-op-in-flight";
                    return false;
                }

                // 2. Directive #5.48 Priority 4: P2 still has real pending choice
                if (P2PendingChoiceCount > 0 || FlowCoordinator.HasPendingP2Choice(player2))
                {
                    blockReason = "p2-pending-choice";
                    return false;
                }

                // Directive #5.48 Priority 2: P1 is gathering player choice
                if (IsPlayer1InChoiceScreen())
                {
                    blockReason = "p1-gathering-choice";
                    return false;
                }

                // 3. Potion continuation is waiting
                if (PendingPotionContinuation || (HasTriggeredPotionContinuationThisTurn && !PotionContinuationExecutedPlayThisTurn && (DateTime.UtcNow - PotionContinuationRequestTime).TotalSeconds < 10.0))
                {
                    blockReason = "potion-continuation-pending";
                    return false;
                }

                // 4. Solver is searching or deploying
                string staleReason;
                if (IsSolverGenuinelyActive(player2, GetP2QueuePlayCardCount(player2.NetId), IsPlayer2ActionInFlight(), out staleReason))
                {
                    blockReason = "solver-active";
                    return false;
                }
                else if (staleReason != null)
                {
                    ClearStaleSolverState(staleReason);
                }

                // 5. P2 still has usable hand cards and energy
                // Directive #5.90 T1: unless CombatSolver already satisfied its plan for this turn
                // (played all planned cards / deliberately stood pat against non-attacking enemies),
                // in which case "cards-affordable" must not keep blocking the end turn.
                bool hasAttack;
                bool hasUsable = P2HasUsableCard(player2, out hasAttack);
                int energy = player2.PlayerCombatState != null ? player2.PlayerCombatState.Energy : 0;
                if (hasUsable && energy > 0 && !P2FallbackExhaustedThisTurn && !HasSolverSatisfiedTurnPlan(player2, state))
                {
                    if (!LifelineContinuationAttemptedThisTurn)
                    {
                        blockReason = "cards-affordable";
                        return false;
                    }
                }

                return true;
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] CheckForceEndTurnGuard exception: " + ex);
                return true;
            }
        }

        public static void ForceEndTurnForPlayer2(CombatManager cm, CombatState state, Player player2)
        {
            try
            {
                if (!IsInCombat()) { DisarmIndependentP2Lifeline("force-end-not-in-combat"); return; }
                if (AreAllPlayersDead() || IsTerminalCombatFinalized)
                {
                    DisarmIndependentP2Lifeline("all-players-dead");
                    LogTerminalCombatFinalized("all-players-dead");
                    return;
                }

                string blockReason;
                if (!CheckForceEndTurnGuard(cm, state, player2, "ForceEndTurnForPlayer2", out blockReason))
                {
                    if (blockReason == "cards-affordable")
                    {
                        if (IsPlayer1Dead())
                        {
                            bool handled = CheckDeadP1ZeroProgressFallback("force-end-cards-affordable-dead-p1");
                            if (handled) return;
                        }

                        LifelineContinuationAttemptedThisTurn = true;
                        ClearStaleSolverState("lifeline-cards-affordable");

                        if (!PlanEmptyRecalcRequestedThisTurn)
                        {
                            GD.Print("[AiTeammate][Coord] p2-force-end-blocked owner=P2 reason=cards-affordable recovery=recalc");
                            PlanEmptyRecalcRequestedThisTurn = true;
                            PlanEmptyRecoveryInProgress = true;
                            PlanEmptyRecoveryStartTime = DateTime.UtcNow;
                            lock (LifelineGate)
                            {
                                IndependentLifelineStartTime = DateTime.UtcNow;
                                IndependentLifelineFired = false;
                            }
                            RequestRecalculation(state, "lifeline-cards-affordable");
                            return;
                        }

                        if (!P2FallbackGreedyUsedThisTurn)
                        {
                            GD.Print("[AiTeammate][Coord] p2-force-end-blocked owner=P2 reason=cards-affordable recovery=fallback");
                            PlanEmptyFallbackRequestedThisTurn = true;
                            GD.Print(string.Format("[AiTeammate][Coord] p2-plan-empty-fallback-requested turn={0}", TurnNumber));
                            bool enqueued = TryFallbackGreedy(player2);
                            if (enqueued)
                            {
                                lock (LifelineGate)
                                {
                                    IndependentLifelineStartTime = DateTime.UtcNow;
                                    IndependentLifelineFired = false;
                                }
                                return;
                            }
                        }

                        GD.Print("[AiTeammate][Coord] p2-force-end-blocked owner=P2 reason=cards-affordable recovery=failed");
                        PlanEmptyRecoveryInProgress = false;
                    }
                    else
                    {
                        GD.Print(string.Format("[AiTeammate][Coord] p2-force-end-blocked owner=P2 reason={0}", blockReason));
                        if (!LifelineContinuationAttemptedThisTurn)
                        {
                            LifelineContinuationAttemptedThisTurn = true;
                            lock (LifelineGate)
                            {
                                IndependentLifelineStartTime = DateTime.UtcNow;
                                IndependentLifelineFired = false;
                            }
                            GD.Print("[AiTeammate][Coord] p2-lifeline-recovery: re-arming lifeline turn=" + TurnNumber);
                        }
                        return;
                    }
                }
                DisarmIndependentP2Lifeline("force-end-path");
                P2TurnEndReason = "force-end";
                LogTurnSummary("ForceEndTurnForPlayer2");

                HasCompletedDeploymentThisTurn = true;

                // R2-4: a leftover P2 choice overlay (loot/"战利品" reward, card grid) must never
                // survive a forced end turn — it soft-locked P1's UI on 10-26.
                FlowCoordinator.ResolveOrClearP2ChoiceOverlays("force-end-turn");

                bool needControlSwitch = !FixedP1CombatControl;
                if (needControlSwitch)
                {
                    GD.Print("[AiTeammate][Coord] ForceEndTurnForPlayer2: switching control to P2 (" + player2.NetId + ") with UI suppressed");
                    TurnFlowPatches.SwitchControlToPlayer(player2.NetId, "wakuu-stall-endturn", true);
                }

                try
                {
                    using (EnterP2ActionSenderScope("ForceEndTurnForPlayer2"))
                    {
                        GD.Print("[AiTeammate][Coord] ForceEndTurnForPlayer2: invoking PlayerCmd.EndTurn for P2");
                        PlayerCmd.EndTurn(player2, false, null);
                    }
                }
                catch (Exception exCmd)
                {
                    GD.PrintErr("[AiTeammate][Coord] ForceEndTurnForPlayer2 PlayerCmd.EndTurn failed: " + exCmd);
                    if (cm != null)
                    {
                        try
                        {
                            using (EnterP2ActionSenderScope("ForceEndTurnForPlayer2-fallback"))
                            {
                                GD.Print("[AiTeammate][Coord] ForceEndTurnForPlayer2 fallback: SetReadyToEndTurn");
                                cm.SetReadyToEndTurn(player2, true, null);
                            }
                        }
                        catch (Exception exCm)
                        {
                            GD.PrintErr("[AiTeammate][Coord] SetReadyToEndTurn fallback failed: " + exCm);
                        }
                    }
                }
                finally
                {
                    if (needControlSwitch)
                    {
                        GD.Print("[AiTeammate][Coord] ForceEndTurnForPlayer2: restoring Player 1 control");
                        TurnFlowPatches.RestorePlayer1ControlIfActive("wakuu-stall-endturn");
                    }
                }
            }
            catch (Exception ex)
            {
                GD.PrintErr("[AiTeammate][Coord] ForceEndTurnForPlayer2 error: " + ex);
            }
        }

        public static bool HasPlayableCards(Player player)

        {

            if (player == null) return false;

            try

            {

                var handPile = PileType.Hand.GetPile(player);

                if (handPile == null || handPile.Cards == null) return false;

                var cards = handPile.Cards;

                for (int i = 0; i < cards.Count; i++)

                {

                    var c = cards[i];

                    if (c != null && CheckIsPlayable(c) && IsAffordable(c, player))

                    {

                        return true;

                    }

                }

            }

            catch { }

            return false;

        }



        public static bool IsMonsterAttacking(Creature c)

        {

            if (c == null || !c.IsMonster || !c.IsAlive) return false;

            try

            {

                var monster = c.Monster;

                if (monster == null) return false;

                var nextMove = monster.NextMove;

                if (nextMove == null || nextMove.Intents == null) return false;



                foreach (var intent in nextMove.Intents)

                {

                    if (intent == null) continue;

                    string typeName = intent.GetType().Name;

                    if (typeName.IndexOf("Attack", StringComparison.OrdinalIgnoreCase) >= 0 ||

                        typeName.IndexOf("DeathBlow", StringComparison.OrdinalIgnoreCase) >= 0)

                    {

                        return true;

                    }

                    var iType = intent.IntentType.ToString();

                    if (iType.IndexOf("Attack", StringComparison.OrdinalIgnoreCase) >= 0 ||

                        iType.IndexOf("DeathBlow", StringComparison.OrdinalIgnoreCase) >= 0)

                    {

                        return true;

                    }

                }

            }

            catch { }

            return false;

        }



        public static string GetMonsterIntentSignature(Creature c)

        {

            if (c == null || !c.IsMonster || !c.IsAlive) return "dead";

            try

            {

                var monster = c.Monster;

                if (monster == null) return "none";

                var nextMove = monster.NextMove;

                if (nextMove == null) return "no-move";

                var stateId = nextMove.StateId ?? "";

                var intentsList = new List<string>();

                if (nextMove.Intents != null)

                {

                    foreach (var i in nextMove.Intents)

                    {

                        if (i != null) intentsList.Add(i.IntentType.ToString());

                    }

                }

                return stateId + ":" + string.Join("+", intentsList.ToArray());

            }

            catch

            {

                return "err";

            }

        }



        public static void SnapshotEnemyIntents()

        {

            try

            {

                EnemyTurnStartHp.Clear();

                EnemyTurnStartIntents.Clear();

                int attackCount = 0;

                int nonAttackCount = 0;



                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null) return;



                var creatures = state.Creatures;

                if (creatures == null) return;



                for (int i = 0; i < creatures.Count; i++)

                {

                    var c = creatures[i];

                    if (c != null && c.IsMonster && c.IsAlive && c.CombatId.HasValue)

                    {

                        uint cid = c.CombatId.Value;

                        EnemyTurnStartHp[cid] = c.CurrentHp;

                        bool isAttack = IsMonsterAttacking(c);

                        string sig = GetMonsterIntentSignature(c);

                        EnemyTurnStartIntents[cid] = sig;



                        if (isAttack) attackCount++;

                        else nonAttackCount++;

                    }

                }



                TurnStartIntentsSummary = string.Format("intents=[attack×{0}, non-attack×{1}]", attackCount, nonAttackCount);

                GD.Print("[AiTeammate][Coord] " + TurnStartIntentsSummary);

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] SnapshotEnemyIntents error: " + ex);

                TurnStartIntentsSummary = "intents=[attack×0, non-attack×0]";

            }

        }



        public static void CheckMidturnReplan(string explicitTrigger)

        {

            try

            {

                // Directive #4.0: Midturn replan switch gate

                if (!MidturnEnabled) return;

                if (!IsInCombat()) return;

                if (!HoldActive || HasReleasedHoldThisTurn) return;



                var now = DateTime.UtcNow;

                if ((now - LastMidturnReplanTime).TotalSeconds < 3.0) return;

                if (MidturnReplanCount >= 2) return;



                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null || state.Players == null || state.Players.Count < 2) return;



                var player2 = state.Players[state.Players.Count - 1];

                if (player2 == null || player2.Creature == null || !player2.Creature.IsAlive) return;



                if (!HasPlayableCards(player2))

                {

                    return;

                }



                string trigger = explicitTrigger;

                if (string.IsNullOrEmpty(trigger))

                {

                    var creatures = state.Creatures;

                    if (creatures != null)

                    {

                        foreach (var kvp in EnemyTurnStartHp)

                        {

                            var id = kvp.Key;

                            int startHp = kvp.Value;

                            bool stillAlive = false;

                            for (int i = 0; i < creatures.Count; i++)

                            {

                                var c = creatures[i];

                                if (c != null && c.CombatId.HasValue && c.CombatId.Value == id && c.IsAlive)

                                {

                                    stillAlive = true;

                                    if (startHp - c.CurrentHp >= 10)

                                    {

                                        trigger = "enemy-hp-dropped: id=" + id + " delta=" + (startHp - c.CurrentHp);

                                        break;

                                    }

                                    string curSig = GetMonsterIntentSignature(c);

                                    string snapSig;

                                    if (EnemyTurnStartIntents.TryGetValue(id, out snapSig) && curSig != snapSig)

                                    {

                                        trigger = "enemy-intent-changed: id=" + id + " from=" + snapSig + " to=" + curSig;

                                        break;

                                    }

                                }

                            }

                            if (trigger != null) break;

                            if (!stillAlive)

                            {

                                trigger = "enemy-died: id=" + id;

                                break;

                            }

                        }

                    }

                }



                if (string.IsNullOrEmpty(trigger)) return;



                MidturnReplanCount++;

                LastMidturnReplanTime = now;

                GD.Print("[AiTeammate][Coord] midturn-replan trigger=" + trigger);



                RequestRecalculation(state, "midturn-replan: " + trigger);

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CheckMidturnReplan error: " + ex);

            }

        }



        public static void CheckHoldRelease(DateTime now)

        {

            try

            {

                if (!HoldActive || HasReleasedHoldThisTurn) return;



                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null || state.Players == null || state.Players.Count < 2) return;



                var player1 = state.Players[0];

                var player2 = state.Players[state.Players.Count - 1];

                if (player1 == null || player2 == null) return;



                // Condition 1: P1 ended turn

                if (cm.IsPlayerReadyToEndTurn(player1))

                {

                    ReleaseHold("p1-end-turn");

                    return;

                }



                // Condition 2: 8.0s timeout since hold started

                if (HoldStartTime != DateTime.MinValue && (now - HoldStartTime).TotalSeconds >= 8.0)

                {

                    ReleaseHold("timeout");

                    return;

                }



                // Condition 3: P2 has no payable playable cards AND no recalculation in flight

                bool isRecalcInFlight = (RecalcRequestedThisTurn && !RecalcSucceeded);

                if (!isRecalcInFlight && !HasPlayableCards(player2))

                {

                    ReleaseHold("no-playable-cards");

                    return;

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] CheckHoldRelease error: " + ex);

                ReleaseHold("fail-open-error");

            }

        }



        public static void ReleaseHold(string reason)

        {

            try

            {

                if (HasReleasedHoldThisTurn) return;

                HasReleasedHoldThisTurn = true;

                HoldActive = false;

                GD.Print("[AiTeammate][Coord] hold-release reason=" + reason);



                var cm = CombatManager.Instance;

                if (cm == null) return;

                var state = cm.DebugOnlyGetState();

                if (state == null || state.Players == null || state.Players.Count < 2) return;



                var player2 = state.Players[state.Players.Count - 1];

                if (player2 == null || player2.Creature == null || !player2.Creature.IsAlive) return;



                if (PendingP2EndTurn || !cm.IsPlayerReadyToEndTurn(player2))

                {

                    ModEntry.SuppressControlSwitchUi = true;

                    try

                    {

                        GD.Print("[AiTeammate][Coord] Dispatching P2 end turn after hold release.");

                        PlayerCmd.EndTurn(player2, false, null);

                    }

                    catch (Exception exCmd)

                    {

                        GD.PrintErr("[AiTeammate][Coord] PlayerCmd.EndTurn on hold release failed: " + exCmd);

                        try { cm.SetReadyToEndTurn(player2, true, null); } catch { }

                    }

                    finally

                    {

                        ModEntry.SuppressControlSwitchUi = false;

                    }

                }

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] ReleaseHold fail-open exception: " + ex);

            }

        }



        public static void LogTurnSummary(string source)

        {

            try

            {

                var cm = CombatManager.Instance;

                var state = cm != null ? cm.DebugOnlyGetState() : null;

                int turn = TurnNumber;

                int p2EnergySpent = 0;

                int p2HandRemaining = 0;

                int p2PayableAttacksLeft = 0;



                if (state != null)

                {

                    turn = state.RoundNumber;

                    if (state.Players != null && state.Players.Count >= 2)

                    {

                        var p2 = state.Players[state.Players.Count - 1];

                        if (p2 != null && p2.PlayerCombatState != null)

                        {

                            int endEnergy = p2.PlayerCombatState.Energy;

                            if (P2TurnStartEnergy >= 0)

                            {

                                p2EnergySpent = Math.Max(0, P2TurnStartEnergy - endEnergy);

                            }

                            var handPile = PileType.Hand.GetPile(p2);

                            if (handPile != null && handPile.Cards != null)

                            {

                                p2HandRemaining = handPile.Cards.Count;

                                foreach (var c in handPile.Cards)

                                {

                                    if (c != null && IsAttack(c) && CheckIsPlayable(c) && IsAffordable(c, p2))

                                    {

                                        p2PayableAttacksLeft++;

                                    }

                                }

                            }

                        }

                    }

                }



                string summary = string.Format("[AiTeammate][Coord] turn-summary turn={0} p2_energy_spent={1} p2_hand_remaining={2} p2_payable_attacks_left={3}", turn, p2EnergySpent, p2HandRemaining, p2PayableAttacksLeft);

                if (!string.IsNullOrEmpty(TurnStartIntentsSummary))

                {

                    summary += " " + TurnStartIntentsSummary;

                }

                if (p2EnergySpent == 0 && p2HandRemaining > 0)

                {

                    summary += " suspicious-empty-turn";

                }

                if (p2EnergySpent == 0 && p2PayableAttacksLeft > 0)

                {

                    summary += " solver-held-attacks";

                }

                GD.Print(summary);

            }

            catch (Exception ex)

            {

                GD.PrintErr("[AiTeammate][Coord] LogTurnSummary error: " + ex);

            }

        }

        public static string DescribeP2Hand(Player p2)
        {
            try
            {
                var hand = p2 != null ? PileType.Hand.GetPile(p2) : null;
                if (hand == null || hand.Cards == null) return "[]";
                var ids = new List<string>();
                foreach (var card in hand.Cards) if (card != null) ids.Add(card.Id.ToString());
                return "[" + string.Join(",", ids.ToArray()) + "]";
            }
            catch { return "[error]"; }
        }

